// Frame pad per style
function getFramePad(mode, style) {
  const b = PAD[mode];
  if (!style || style === "classic") return b;
  if (style === "thin")  return { t:Math.round(b.t/2), l:Math.round(b.l/2), r:Math.round(b.r/2), b:Math.round(b.b/2) };
  if (style === "strip") return { t:0, l:0, r:0, b: mode==="landscape" ? 120 : 210 };
  return { t:0, l:0, r:0, b:0 }; // "none"
}
