const RTL_CHAR_RE = /[\u0590-\u05FF\u0600-\u06FF]/;
function inferTextDirection(text = "", fallback = "ltr") {
  if (typeof fallback === "string" && (fallback === "rtl" || fallback === "ltr")) {
    if (fallback === "rtl" || fallback === "ltr") {
      const normalizedText = String(text || "");
      if (!normalizedText.trim()) return fallback;
    }
  }
  return RTL_CHAR_RE.test(String(text || "")) ? "rtl" : "ltr";
}

function getMobilePreviewDirection(text = "", fallback = "ltr") {
  const normalizedText = String(text || "");
  if (!normalizedText.trim()) return inferTextDirection(normalizedText, fallback);
  // iPhone/WebKit drifts Hebrew stroke rendering to the right when the preview path
  // keeps RTL anchoring. Keep the mobile preview anchored like LTR text instead.
  return RTL_CHAR_RE.test(normalizedText) ? "ltr" : inferTextDirection(normalizedText, fallback);
}

function getMobileEditingDirection(text = "", fallback = "ltr") {
  return inferTextDirection(text, fallback);
}

function getBaseFrameSizeCm(mode) {
  return FRAME_SIZE_CM[mode] || FRAME_SIZE_CM.landscape;
}

function getAdjustedFrameSizeCm(mode, printSizeAdj = {}) {
  const base = getBaseFrameSizeCm(mode);
  const adj = printSizeAdj?.[mode] || { w: 0, h: 0 };
  return {
    w: Math.max(0.1, base.w + (Number.isFinite(adj.w) ? adj.w : 0)),
    h: Math.max(0.1, base.h + (Number.isFinite(adj.h) ? adj.h : 0)),
  };
}

function getExportPixelSize(mode, printDpi, printSizeAdj = {}) {
  const sizeCm = getAdjustedFrameSizeCm(mode, printSizeAdj);
  const dpi = Number.isFinite(printDpi) && printDpi > 0 ? printDpi : 300;
  const pxPerCm = dpi / 2.54;
  return {
    width: Math.max(1, Math.round(sizeCm.w * pxPerCm)),
    height: Math.max(1, Math.round(sizeCm.h * pxPerCm)),
  };
}

function readStoredWatermarkConfig(ph = PH) {
  let stored = {};
  try {
    stored = JSON.parse(localStorage.getItem("wm_settings") || "{}") || {};
  } catch (e) {
    stored = {};
  }
  const strokeW = Number(stored?.strokeW);
  const size = Number(stored?.size);
  return {
    color: stored?.color || "#888888",
    stroke: stored?.stroke ?? false,
    shadow: stored?.shadow ?? true,
    name: stored?.name || ph?.name || "",
    phone: stored?.phone || ph?.phone || "",
    font: stored?.font || "Heebo",
    bg: stored?.bg ?? false,
    strokeW: Number.isFinite(strokeW) ? strokeW : 0.4,
    size: Number.isFinite(size) ? size : 1,
    strokeColor: stored?.strokeColor || "#000000",
  };
}

function dataUrlToBlob(dataUrl = "") {
  const raw = String(dataUrl || "");
  if (!raw.startsWith("data:")) throw new Error("Invalid data URL");
  const [meta, base64] = raw.split(",", 2);
  const mime = (meta.match(/^data:(.*?);base64$/i)?.[1] || "application/octet-stream").trim();
  const binary = atob(base64 || "");
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}

function triggerBlobDownload(blob, fileName = "download.bin") {
  if (!(blob instanceof Blob)) throw new Error("Missing blob for download");
  const url = URL.createObjectURL(blob);
  try {
    const a = document.createElement("a");
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  } finally {
    window.setTimeout(() => URL.revokeObjectURL(url), 1200);
  }
}

function crc32ForExportPng(data) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      crc = (crc & 1) ? (0xEDB88320 ^ (crc >>> 1)) : (crc >>> 1);
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function injectExportPngDpi(dataUrl, dpi) {
  try {
    const base64 = dataUrl.split(",")[1];
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const ppm = Math.round(dpi * 39.3701);
    const phys = new Uint8Array(21);
    phys[0] = 0; phys[1] = 0; phys[2] = 0; phys[3] = 9;
    phys[4] = 0x70; phys[5] = 0x48; phys[6] = 0x59; phys[7] = 0x73;
    phys[8] = (ppm >> 24) & 0xFF; phys[9] = (ppm >> 16) & 0xFF; phys[10] = (ppm >> 8) & 0xFF; phys[11] = ppm & 0xFF;
    phys[12] = (ppm >> 24) & 0xFF; phys[13] = (ppm >> 16) & 0xFF; phys[14] = (ppm >> 8) & 0xFF; phys[15] = ppm & 0xFF;
    phys[16] = 1;
    const crc = crc32ForExportPng(phys.slice(4, 17));
    phys[17] = (crc >> 24) & 0xFF; phys[18] = (crc >> 16) & 0xFF; phys[19] = (crc >> 8) & 0xFF; phys[20] = crc & 0xFF;
    const result = new Uint8Array(bytes.length + 21);
    result.set(bytes.slice(0, 33));
    result.set(phys, 33);
    result.set(bytes.slice(33), 54);
    let str = "";
    result.forEach((b) => { str += String.fromCharCode(b); });
    return `data:image/png;base64,${btoa(str)}`;
  } catch (e) {
    console.warn("pHYs inject failed:", e);
    return dataUrl;
  }
}

function extractUiFontFamily(fontFamily = "") {
  const raw = String(fontFamily || "").trim();
  if (!raw) return "Heebo";
  const first = raw.split(",")[0] || raw;
  return first.replace(/^['"]+|['"]+$/g, "").trim() || "Heebo";
}

function resolveFabricFontFamily(fontFamily = "", text = "") {
  const uiFont = extractUiFontFamily(fontFamily);
  const fallback = FABRIC_FONT_FALLBACKS[uiFont];
  if (fallback && RTL_CHAR_RE.test(String(text || ""))) {
    // Fabric can measure with the first family but render Hebrew with a later
    // browser fallback, which desyncs the selection box. Use the supported
    // Hebrew family directly on-canvas to keep metrics and paint aligned.
    return fallback;
  }
  return uiFont;
}

function collectTextRenderFontFamilies(items = []) {
  const families = new Set();
  (Array.isArray(items) ? items : []).forEach((item) => {
    if (!item) return;
    const baseFontFamily = item._uiFontFamily || item.fontFamily || "Heebo";
    const uiFontFamily = extractUiFontFamily(baseFontFamily);
    if (uiFontFamily) families.add(uiFontFamily);
    const resolvedFamily = resolveFabricFontFamily(baseFontFamily, item.text || "");
    if (resolvedFamily) families.add(resolvedFamily);
    const fallbackFamily = FABRIC_FONT_FALLBACKS[uiFontFamily];
    if (fallbackFamily) families.add(fallbackFamily);
  });
  return [...families].filter(Boolean);
}

async function waitForTextRenderFonts(items = []) {
  if (typeof document === "undefined" || !document.fonts) return;
  const fontFamilies = collectTextRenderFontFamilies(items);
  if (!fontFamilies.length) {
    if (document.fonts.ready?.then) {
      try { await Promise.resolve(document.fonts.ready); } catch (e) {}
    }
    return;
  }
  if (document.fonts.load) {
    await Promise.allSettled(fontFamilies.map((family) => document.fonts.load(`16px "${family}"`)));
  }
  if (document.fonts.ready?.then) {
    try { await Promise.resolve(document.fonts.ready); } catch (e) {}
  }
}

