function classifyIconCategory(rawName) {
  // Existing Flyer-based files
  if (/White[- ]?Red|Hearts?/i.test(rawName)) return "לבבות";
  if (/Flyer-\(6\)/i.test(rawName)) return "פרחים";
  if (/Flyer-\((8|9)\)/i.test(rawName)) return "חתונה";
  if (/Flyer-\((2|7)\)/i.test(rawName)) return "צמחים";
  // Normalize: strip duplicate suffix like " (1)"
  const base = rawName.replace(/\s*\(\d+\)\s*$/, "").trim();
  if (_HASH_CAT[base]) return _HASH_CAT[base];
  // Numbered pngegg
  const numM = base.match(/^pngegg \((\d+)\)$/);
  if (numM) {
    const n = +numM[1];
    if (n === 38) return "לבבות";
    if (n === 42 || n === 43) return "חתונה";
    if (_PEG_CACTUS.has(n)) return "צמחים";
    if (_PEG_FLOWERS.has(n)) return "פרחים";
    if (_PEG_LEAVES.has(n)) return "צמחים";
    return "צמחים"; // safe fallback for unknown numbered pngegg
  }
  // Timestamp-named pngegg
  const tsM = base.match(/^pngegg - 2025-01-06T(\d{6})/);
  if (tsM) {
    if (_PEG_TS_FLOWERS.has(tsM[1])) return "פרחים";
    if (_PEG_TS_LEAVES.has(tsM[1])) return "צמחים";
    return "צמחים"; // safe fallback for unknown timestamped pngegg
  }
  // Keyword patterns
  if (/cactus/i.test(base)) return "צמחים";
  if (/newborn|baby|infant/i.test(base)) return "ברית\\ה";
  if (/flower|floral|daisy|chamomile|bouquet|pngtree/i.test(base)) return "פרחים";
  if (/imgbin|openart/i.test(base)) return "חיות";
  return "חיות"; // fallback — unknown items go to animals tab
}

const ICON_ASSETS = Object.entries({
  ...import.meta.glob("./elements-14.3/*.png", { eager: true, import: "default" }),
  ...import.meta.glob("./elements-14.3/*.jpg", { eager: true, import: "default" }),
})
  // Remove duplicate files (those ending with " (1)", " (2)", etc.)
  .filter(([path]) => !/ \(\d+\)\.(png|jpg)$/i.test(path))
  .map(([path, src]) => {
    const raw = path.split("/").pop()?.replace(/\.(png|jpg)$/i, "") || "icon";
    const name = raw
      .replace(/[_-]+/g, " ")
      .replace(/\s*\(\d+\)\s*/g, " ")
      .replace(/\s*_?\d+\s*Layer\s*\d+/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
    return { id: raw, name: name || raw, src, category: classifyIconCategory(raw) };
  })
  .sort((a, b) => a.name.localeCompare(b.name));

const ICON_ASSET_SRC_BY_ID = new Map(ICON_ASSETS.map(a => [a.id, a.src]));
const ICON_ASSET_SRC_BY_ID_CI = new Map(ICON_ASSETS.map(a => [a.id.toLowerCase(), a.src]));

const ICON_ASSETS_BY_CATEGORY = ELEMENT_TAB_LABELS.slice(1).reduce((acc, label) => {
  if (label === SHAPES_TAB_LABEL) return acc;
  acc[label] = ICON_ASSETS.filter(icon => icon.category === label);
  return acc;
}, {});

function getElementCategoryCount(label) {
  if (label === "Emoji") return EMOJIS.length;
  if (label === SHAPES_TAB_LABEL) return SHAPE_PRESETS.length;
  return (ICON_ASSETS_BY_CATEGORY[label] || []).length;
}

function getSafeColorInputValue(value, fallback = "#C9A96E") {
  const raw = String(value || "").trim();
  if (/^#[0-9a-f]{6}$/i.test(raw)) return raw.toUpperCase();
  if (/^#[0-9a-f]{3}$/i.test(raw)) {
    return `#${raw[1]}${raw[1]}${raw[2]}${raw[2]}${raw[3]}${raw[3]}`.toUpperCase();
  }
  return fallback.toUpperCase();
}

function isStrokeOnlyShapePreset(preset = {}) {
  return !!(preset?.strokeOnly || preset?.kind === "line" || preset?.kind === "outline-square");
}

const EDITABLE_VECTOR_SHAPE_TYPES = new Set(["circle", "rect", "triangle", "ellipse", "polygon", "polyline", "path", "line"]);

function isTransparentLikeFill(fill) {
  if (fill == null || fill === "" || fill === "transparent" || fill === "none") return true;
  return /^rgba?\(\s*0\s*,\s*0\s*,\s*0\s*,\s*0(?:\.0+)?\s*\)$/i.test(String(fill).trim());
}

function getEditableShapeParts(obj = {}) {
  if (!obj || typeof obj !== "object") return [];
  if (EDITABLE_VECTOR_SHAPE_TYPES.has(obj.type)) return [obj];
  if (obj.type === "group" && Array.isArray(obj._objects)) {
    return obj._objects.flatMap(getEditableShapeParts);
  }
  return [];
}

function isEditableShapeObject(obj = {}) {
  return !!(obj?._isShapeElement || getEditableShapeParts(obj).length);
}

function getLineShapePart(obj = {}) {
  return getEditableShapeParts(obj).find((part) => part?.type === "line") || null;
}

function isLineShapeObject(obj = {}) {
  return !!(obj && (
    obj?._shapeKind === "line"
    || obj?.type === "line"
    || (!!getLineShapePart(obj) && obj?._shapeKind === "line")
  ));
}

function isStrokeOnlyShapeObject(obj = {}) {
  if (!isEditableShapeObject(obj)) return false;
  if (obj?._shapeStrokeOnly || isLineShapeObject(obj) || obj?._shapeKind === "outline-square" || obj?.type === "line") {
    return true;
  }
  const parts = getEditableShapeParts(obj);
  return parts.length > 0 && parts.every((part) => isTransparentLikeFill(part?.fill) && !!part?.stroke);
}

function getShapePrimaryPart(obj = {}) {
  return getEditableShapeParts(obj)[0] || obj;
}

function getShapeObjectColor(obj = {}, fallback = "#C9A96E") {
  const primary = getShapePrimaryPart(obj);
  const preferred = isStrokeOnlyShapeObject(obj)
    ? (primary?.stroke || primary?.fill || fallback)
    : (primary?.fill || primary?.stroke || fallback);
  return getSafeColorInputValue(preferred, fallback);
}

function getShapeObjectStrokeWidth(obj = {}, fallback = 4) {
  const primary = getShapePrimaryPart(obj);
  return Math.max(0, Math.round(primary?.strokeWidth || fallback));
}

function getShapeCornerRadius(obj = {}, fallback = 0) {
  const rect = getEditableShapeParts(obj).find((part) => part?.type === "rect" && (part?.width || 0) > 18 && (part?.height || 0) > 18);
  return Math.max(0, Math.round(Math.max(rect?.rx || 0, rect?.ry || 0, fallback)));
}

function shapeSupportsCornerRadius(obj = {}) {
  return getEditableShapeParts(obj).some((part) => part?.type === "rect" && (part?.width || 0) > 18 && (part?.height || 0) > 18);
}

function applyShapeUpdates(obj = {}, props = {}) {
  if (!isEditableShapeObject(obj) || !props || typeof props !== "object") return { ...props };
  const nextProps = { ...props };
  const parts = getEditableShapeParts(obj);
  if (!parts.length) return nextProps;

  const hasCornerRadius = Object.prototype.hasOwnProperty.call(nextProps, "cornerRadius");
  const nextRadius = hasCornerRadius
    ? Math.max(0, Number(nextProps.cornerRadius) || 0)
    : null;

  parts.forEach((part) => {
    if (!part?.set) return;
    const patch = {};
    const strokeOnly = isStrokeOnlyShapeObject(part);

    if (Object.prototype.hasOwnProperty.call(nextProps, "fill") && !strokeOnly) {
      patch.fill = nextProps.fill;
    }
    if (Object.prototype.hasOwnProperty.call(nextProps, "stroke") && (strokeOnly || part?.stroke != null || isTransparentLikeFill(part?.fill))) {
      patch.stroke = nextProps.stroke;
    }
    if (Object.prototype.hasOwnProperty.call(nextProps, "strokeWidth") && (strokeOnly || part?.stroke != null || part?.type === "line")) {
      patch.strokeWidth = nextProps.strokeWidth;
    }
    if (Object.prototype.hasOwnProperty.call(nextProps, "paintFirst")) {
      patch.paintFirst = nextProps.paintFirst;
    }
    if (part?.type === "rect") {
      const rx = hasCornerRadius
        ? nextRadius
        : (Object.prototype.hasOwnProperty.call(nextProps, "rx") ? Math.max(0, Number(nextProps.rx) || 0) : null);
      const ry = hasCornerRadius
        ? nextRadius
        : (Object.prototype.hasOwnProperty.call(nextProps, "ry") ? Math.max(0, Number(nextProps.ry) || 0) : rx);
      if (rx != null || ry != null) {
        const safeRadius = Math.max(0, rx ?? ry ?? 0);
        patch.rx = Math.min(safeRadius, Math.max(0, (part.width || 0) / 2));
        patch.ry = Math.min(ry ?? patch.rx ?? 0, Math.max(0, (part.height || 0) / 2));
        patch._shapeCornerRadius = patch.rx;
      }
      patch.strokeUniform = true;
    }
    if (part?.type === "line") {
      patch.strokeUniform = true;
      patch.strokeLineCap = part.strokeLineCap || "round";
    }

    if (Object.keys(patch).length) {
      part.set(patch);
      if (typeof part._setWidthHeight === "function" && part.type === "line") {
        part._setWidthHeight();
      }
      part.setCoords?.();
    }
  });

  delete nextProps.fill;
  delete nextProps.stroke;
  delete nextProps.strokeWidth;
  delete nextProps.paintFirst;
  delete nextProps.cornerRadius;
  delete nextProps.rx;
  delete nextProps.ry;
  return nextProps;
}

function normalizeShapeAfterTransform(obj, canvas = null) {
  if (!isEditableShapeObject(obj)) return;
  if (isLineShapeObject(obj) && obj?.type === "group") {
    const part = getLineShapePart(obj);
    if (part?.set) {
      const scaleX = typeof obj.scaleX === "number" && Number.isFinite(obj.scaleX) ? obj.scaleX : 1;
      const scaleY = typeof obj.scaleY === "number" && Number.isFinite(obj.scaleY) ? obj.scaleY : 1;
      if (Math.abs(scaleX - 1) > 0.001 || Math.abs(scaleY - 1) > 0.001) {
        part.set({
          x1: (part.x1 || 0) * scaleX,
          y1: (part.y1 || 0) * scaleY,
          x2: (part.x2 || 0) * scaleX,
          y2: (part.y2 || 0) * scaleY,
          strokeUniform: true,
          strokeLineCap: part.strokeLineCap || "round",
        });
        part._setWidthHeight?.();
        obj.set({ scaleX: 1, scaleY: 1 });
      }
      part.setCoords?.();
    }
    obj.setCoords?.();
    canvas?.requestRenderAll?.();
    return;
  }
  getEditableShapeParts(obj).forEach((part) => {
    if (!part?.set) return;
    if (part.type === "rect") {
      const scaleX = typeof part.scaleX === "number" && Number.isFinite(part.scaleX) ? part.scaleX : 1;
      const scaleY = typeof part.scaleY === "number" && Number.isFinite(part.scaleY) ? part.scaleY : 1;
      if (Math.abs(scaleX - 1) > 0.001 || Math.abs(scaleY - 1) > 0.001) {
        const nextWidth = Math.max(1, (part.width || 1) * scaleX);
        const nextHeight = Math.max(1, (part.height || 1) * scaleY);
        const radius = Math.max(0, part._shapeCornerRadius ?? part.rx ?? part.ry ?? 0);
        part.set({
          width: nextWidth,
          height: nextHeight,
          scaleX: 1,
          scaleY: 1,
          rx: Math.min(radius, nextWidth / 2),
          ry: Math.min(radius, nextHeight / 2),
          strokeUniform: true,
        });
      }
    }
    if (part.type === "line") {
      const scaleX = typeof part.scaleX === "number" && Number.isFinite(part.scaleX) ? part.scaleX : 1;
      const scaleY = typeof part.scaleY === "number" && Number.isFinite(part.scaleY) ? part.scaleY : 1;
      if (Math.abs(scaleX - 1) > 0.001 || Math.abs(scaleY - 1) > 0.001) {
        const nextX1 = (part.x1 || 0) * scaleX;
        const nextY1 = (part.y1 || 0) * scaleY;
        const nextX2 = (part.x2 || 0) * scaleX;
        const nextY2 = (part.y2 || 0) * scaleY;
        part.set({
          x1: nextX1,
          y1: nextY1,
          x2: nextX2,
          y2: nextY2,
          scaleX: 1,
          scaleY: 1,
          strokeUniform: true,
          strokeLineCap: part.strokeLineCap || "round",
        });
      } else {
        part.set({
          scaleX: 1,
          scaleY: 1,
          strokeUniform: true,
          strokeLineCap: part.strokeLineCap || "round",
        });
      }
      if (typeof part._setWidthHeight === "function") {
        part._setWidthHeight();
      }
    }
    part.setCoords?.();
  });
  obj.setCoords?.();
  canvas?.requestRenderAll?.();
}

function createFabricLineShapeGroup(F, {
  startPoint = { x: 0, y: 0 },
  endPoint = { x: 124, y: 0 },
  stroke = "#C6B39B",
  strokeWidth = 6,
  opacity = 0.9,
  id = `shape-line-${Date.now()}`,
  name = "קו",
} = {}) {
  if (!F) return null;
  const dx = (endPoint?.x || 0) - (startPoint?.x || 0);
  const dy = (endPoint?.y || 0) - (startPoint?.y || 0);
  const length = Math.max(12, Math.hypot(dx, dy));
  const angle = Math.atan2(dy, dx) * (180 / Math.PI);
  const line = new F.Line([0, 0, length, 0], {
    left: startPoint?.x || 0,
    top: startPoint?.y || 0,
    originX: "left",
    originY: "center",
    angle,
    stroke,
    strokeWidth: Math.max(1, strokeWidth || 1),
    strokeLineCap: "round",
    strokeUniform: true,
    fill: null,
    selectable: true,
    evented: true,
    objectCaching: false,
    noScaleCache: true,
    padding: 12,
    perPixelTargetFind: true,
    id,
    _emoName: name,
    _elementName: name,
    _isShapeElement: true,
    _shapeKind: "line",
    _shapeStrokeOnly: true,
    _lineLayout: "anchored-start",
    _lineLength: length,
  });
  line._setWidthHeight?.();
  line.opacity = typeof opacity === "number" ? opacity : 0.9;
  line.hoverCursor = "move";
  line.moveCursor = "move";
  line.lockScalingX = true;
  line.lockScalingY = true;
  line.lockSkewingX = true;
  line.lockSkewingY = true;
  line.lockRotation = true;
  line.hasBorders = false;
  line.setCoords?.();
  return line;
}

function getFabricLineLocalPoint(obj, endpoint = "start") {
  const linePart = getLineShapePart(obj);
  if (obj?.type === "group" && linePart) {
    return endpoint === "start"
      ? { x: linePart.x1 || 0, y: linePart.y1 || 0 }
      : { x: linePart.x2 || 0, y: linePart.y2 || 0 };
  }
  if (obj?.type === "line" && obj?._lineLayout === "anchored-start") {
    const length = Math.max(12, Number(obj?._lineLength) || Math.abs((obj?.x2 || 0) - (obj?.x1 || 0)) || 12);
    return endpoint === "start"
      ? { x: 0, y: 0 }
      : { x: length, y: 0 };
  }
  if (!obj) return { x: 0, y: 0 };
  if (typeof obj.calcLinePoints === "function") {
    try {
      const pts = obj.calcLinePoints();
      return endpoint === "start"
        ? { x: pts?.x1 || 0, y: pts?.y1 || 0 }
        : { x: pts?.x2 || 0, y: pts?.y2 || 0 };
    } catch (error) {}
  }
  return endpoint === "start"
    ? { x: obj.x1 || 0, y: obj.y1 || 0 }
    : { x: obj.x2 || 0, y: obj.y2 || 0 };
}

function ShapePresetIcon({ preset }) {
  const fill = preset?.stroke || preset?.fill || "#C9A96E";
  switch (preset?.kind) {
    case "circle":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><circle cx="50" cy="50" r="28" fill={fill} fillOpacity="0.9" /></svg>;
    case "square":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><rect x="24" y="24" width="52" height="52" fill={fill} fillOpacity="0.9" /></svg>;
    case "outline-square":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><rect x="22" y="22" width="56" height="56" fill="none" stroke={fill} strokeWidth="7" /></svg>;
    case "triangle":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><polygon points="50,18 80,78 20,78" fill={fill} fillOpacity="0.9" /></svg>;
    case "diamond":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><path d={STYLIZED_DIAMOND_PATH} fill={fill} fillOpacity="0.9" /></svg>;
    case "hexagon":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><polygon points="31,18 69,18 87,50 69,82 31,82 13,50" fill={fill} fillOpacity="0.9" /></svg>;
    case "bar-horizontal":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><rect x="16" y="44" width="68" height="12" rx="6" ry="6" fill={fill} fillOpacity="0.9" /></svg>;
    case "bar-vertical":
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><rect x="44" y="16" width="12" height="68" rx="6" ry="6" fill={fill} fillOpacity="0.9" /></svg>;
    default:
      return <svg viewBox="0 0 100 100" style={{ width: "74%", height: "74%" }}><circle cx="50" cy="50" r="28" fill={fill} fillOpacity="0.9" /></svg>;
  }
}

// ── Styled background images ──
function parseStyledBgName(rawName = "") {
  const name = String(rawName || "").trim();
  const portraitMatch = name.match(/^(.*?)(?:\s*-\s*|\s+)אורך$/);
  return {
    name,
    baseName: (portraitMatch?.[1] || name).trim(),
    mode: portraitMatch ? "portrait" : "landscape",
  };
}

const BG_IMAGES = Object.entries(
  import.meta.glob("./bg-images/*.png", { eager: true, import: "default" })
).map(([path, src]) => {
  const name = path.split("/").pop()?.replace(/\.png$/i, "") || "";
  return {
    src,
    ...parseStyledBgName(name),
  };
}).sort((a, b) => (
  a.baseName.localeCompare(b.baseName, "he")
  || (a.mode === b.mode ? 0 : (a.mode === "landscape" ? -1 : 1))
));

const BG_IMAGE_BY_NAME = new Map(BG_IMAGES.map(bg => [bg.name, bg]));
const BG_IMAGE_BY_NAME_CI = new Map(BG_IMAGES.map(bg => [bg.name.toLowerCase(), bg]));
const BG_IMAGE_BY_SRC = new Map(BG_IMAGES.map(bg => [bg.src, bg]));

function getStyledBgMeta(input) {
  if (!input) return null;
  if (typeof input === "string") {
    return BG_IMAGE_BY_NAME.get(input) || BG_IMAGE_BY_SRC.get(input) || null;
  }
  if (typeof input === "object" && input?.src) {
    return BG_IMAGE_BY_SRC.get(input.src) || input;
  }
  return null;
}

function resolveStyledBgForMode(input, mode = null) {
  const bg = getStyledBgMeta(input);
  if (!bg) return null;
  if (!mode) return bg;
  return BG_IMAGES.find(candidate => candidate.baseName === bg.baseName && candidate.mode === mode) || bg;
}

function resolveStyledBgSrcForMode(input, mode = null) {
  return resolveStyledBgForMode(input, mode)?.src || null;
}

function resolveStyledBgNameFromSrc(src) {
  return BG_IMAGE_BY_SRC.get(src)?.name || null;
}

const iconSrcLike = (fragment) => ICON_ASSETS.find(icon => icon.id.includes(fragment))?.src;
const iconObj = (src, left, top, scaleX, scaleY, id) => ({
  type:"image",
  src,
  left,
  top,
  scaleX,
  scaleY,
  originX:"center",
  originY:"center",
  id,
  selectable:true,
  evented:true,
});

