const BUILTIN = buildBuiltInTemplates({
  iconsByCategory: Object.fromEntries(
    Object.entries(ICON_ASSETS_BY_CATEGORY).map(([label, icons]) => [label, icons.map((icon) => icon.src)])
  ),
});
const SYSTEM_TEMPLATE_OVERRIDES_FILE_URL = `${import.meta.env.BASE_URL}systemTemplateOverrides.json`;
const SYSTEM_TEMPLATE_OVERRIDES_API_URL = "/api/system-template-overrides";

// IDs of system (non-user) objects
const SAMPLE_PREVIEW_OBJECT_ID = "sample-preview-image";
const SYS = new Set(["wm","hole","holelabel","snap-v","snap-h", SAMPLE_PREVIEW_OBJECT_ID]);
const isTextHaloObject = o => !!(o?._isTextHalo || String(o?.id || "").startsWith(TEXT_HALO_PREFIX));
const isObjectHaloObject = o => !!(o?._isObjectHalo || String(o?.id || "").startsWith(OBJECT_HALO_PREFIX));
const isMobileTextPreviewObject = o => !!(o?._isMobileTextPreview || String(o?.id || "").startsWith(MOBILE_TEXT_PREVIEW_PREFIX));
const isSafeZoneLineObject = o => !!(o?._isSafeZoneLine || String(o?.id || "").startsWith("__safe_zone__"));
const isHaloSystemObject = o => !!(isTextHaloObject(o) || isObjectHaloObject(o));
const isCanvasSystemObject = o => !!(o && (SYS.has(o.id) || isHaloSystemObject(o) || isMobileTextPreviewObject(o) || isSafeZoneLineObject(o)));
const isUser = o => !!(o && !isCanvasSystemObject(o));
const looksLikeTextLayoutId = (id = "") => /invite-(title|name|date|text)|manual-text-user/i.test(String(id || ""));
const looksLikeCenterDecorId = (id = "") => /(heart|ring|center|heart|לב|טבעת|invite-decoration-.*center)/i.test(String(id || ""));

function isArrangedTextLikeObject(obj) {
  if (!obj) return false;
  if (obj.type === "i-text" || obj.type === "textbox") return true;
  return looksLikeTextLayoutId(obj.id);
}

function isArrangedDateLikeObject(obj) {
  if (/date/i.test(String(obj?.id || ""))) return true;
  // Detect date-like text content: DD.MM.YYYY, DD/MM/YY, DD-MM-YYYY, etc.
  const text = String(obj?.text || obj?.content || "").trim();
  return /^\d{1,2}[.\/\-]\d{1,2}[.\/\-]\d{2,4}$/.test(text);
}

// Check if two bounding rects overlap (with optional margin)
function rectsOverlap(a, b, margin = 0) {
  return !(a.left + a.width + margin < b.left || b.left + b.width + margin < a.left ||
           a.top + a.height + margin < b.top || b.top + b.height + margin < a.top);
}

function rectIntersectionArea(a, b) {
  const ra = normalizeSnapRect(a);
  const rb = normalizeSnapRect(b);
  const width = Math.max(0, Math.min(ra.right, rb.right) - Math.max(ra.left, rb.left));
  const height = Math.max(0, Math.min(ra.bottom, rb.bottom) - Math.max(ra.top, rb.top));
  return width * height;
}

function getObjectScaledSize(obj) {
  const width = typeof obj?.getScaledWidth === "function"
    ? obj.getScaledWidth()
    : ((obj?.width || 0) * (typeof obj?.scaleX === "number" ? obj.scaleX : 1));
  const height = typeof obj?.getScaledHeight === "function"
    ? obj.getScaledHeight()
    : ((obj?.height || 0) * (typeof obj?.scaleY === "number" ? obj.scaleY : 1));
  return { width: Math.max(1, width || 1), height: Math.max(1, height || 1) };
}

function normalizeSnapRect(rect = {}) {
  const width = Math.max(1, Number.isFinite(rect.width) ? rect.width : ((rect.right ?? 0) - (rect.left ?? 0)));
  const height = Math.max(1, Number.isFinite(rect.height) ? rect.height : ((rect.bottom ?? 0) - (rect.top ?? 0)));
  const left = Number.isFinite(rect.left) ? rect.left : ((rect.centerX ?? 0) - (width / 2));
  const top = Number.isFinite(rect.top) ? rect.top : ((rect.centerY ?? 0) - (height / 2));
  return {
    left,
    top,
    width,
    height,
    right: left + width,
    bottom: top + height,
    centerX: left + (width / 2),
    centerY: top + (height / 2),
  };
}

function buildSnapRectFromCenter(centerX, centerY, width, height) {
  return normalizeSnapRect({
    left: centerX - (width / 2),
    top: centerY - (height / 2),
    width,
    height,
  });
}

function getSnapRectAnchors(rect) {
  const next = normalizeSnapRect(rect);
  return {
    rect: next,
    x: [
      { key: "left", value: next.left },
      { key: "center", value: next.centerX },
      { key: "right", value: next.right },
    ],
    y: [
      { key: "top", value: next.top },
      { key: "center", value: next.centerY },
      { key: "bottom", value: next.bottom },
    ],
  };
}

function findBestSnapMatch(rect, targets, threshold, axis, activeKeys = null) {
  const normalized = getSnapRectAnchors(rect);
  const anchors = normalized[axis] || [];
  const allowedAnchors = Array.isArray(activeKeys) && activeKeys.length
    ? anchors.filter(anchor => activeKeys.includes(anchor.key))
    : anchors;
  let best = null;
  allowedAnchors.forEach((anchor) => {
    (targets || []).forEach((target) => {
      if (!target || !Number.isFinite(target.value)) return;
      const delta = target.value - anchor.value;
      const distance = Math.abs(delta);
      if (distance > threshold) return;
      if (!best || distance < best.distance) {
        best = {
          axis,
          rect: normalized.rect,
          anchor,
          target,
          delta,
          distance,
          guideValue: target.value,
        };
      }
    });
  });
  return best;
}

function getScaleSnapKeysFromHandle(handle) {
  switch (String(handle || "")) {
    case "ml":
      return { x: ["left"], y: [] };
    case "mr":
      return { x: ["right"], y: [] };
    case "mt":
      return { x: [], y: ["top"] };
    case "mb":
      return { x: [], y: ["bottom"] };
    case "tl":
      return { x: ["left"], y: ["top"] };
    case "tr":
      return { x: ["right"], y: ["top"] };
    case "bl":
      return { x: ["left"], y: ["bottom"] };
    case "br":
      return { x: ["right"], y: ["bottom"] };
    default:
      return { x: ["left", "right"], y: ["top", "bottom"] };
  }
}

function setImageObjectWidth(obj, width) {
  if (!obj || obj.type !== "image") return;
  if (typeof obj.scaleToWidth === "function") {
    obj.scaleToWidth(width);
    return;
  }
  const baseWidth = Math.max(1, obj.width || 1);
  const ratio = width / baseWidth;
  obj.set({ scaleX: ratio, scaleY: ratio });
}

function setRenderableObjectWidth(obj, width) {
  if (!obj || !Number.isFinite(width) || width <= 0) return;
  if (obj.type === "image") {
    setImageObjectWidth(obj, width);
    return;
  }
  const current = getObjectScaledSize(obj);
  if (!current.width) return;
  const ratio = width / Math.max(1, current.width);
  const scaleX = typeof obj.scaleX === "number" ? obj.scaleX : 1;
  const scaleY = typeof obj.scaleY === "number" ? obj.scaleY : 1;
  const signX = scaleX < 0 ? -1 : 1;
  const signY = scaleY < 0 ? -1 : 1;
  obj.set({
    scaleX: Math.max(0.0001, Math.abs(scaleX) * ratio) * signX,
    scaleY: Math.max(0.0001, Math.abs(scaleY) * ratio) * signY,
  });
}

function scaleObjsToMode(objs, srcMode, dstMode) {
  if (!objs || !objs.length || srcMode === dstMode) return objs;
  const srcD = DIMS[srcMode], dstD = DIMS[dstMode];
  const srcP = PAD[srcMode],  dstP = PAD[dstMode];

  // Photo area bounds
  const srcBarTop = srcD.h - srcP.b;
  const dstBarTop = dstD.h - dstP.b;
  const srcPhotoW = srcD.w - srcP.l - srcP.r;
  const srcPhotoH = srcBarTop - srcP.t;
  const dstPhotoW = dstD.w - dstP.l - dstP.r;
  const dstPhotoH = dstBarTop - dstP.t;

  // Center of photo area in each mode
  const srcCX = srcP.l + srcPhotoW / 2;
  const srcCY = srcP.t + srcPhotoH / 2;
  const dstCX = dstP.l + dstPhotoW / 2;
  const dstCY = dstP.t + dstPhotoH / 2;

  // Uniform scale = fit by the narrower axis, keeps composition proportions
  const uniform  = Math.min(dstPhotoW / Math.max(1, srcPhotoW), dstPhotoH / Math.max(1, srcPhotoH));
  const barRatio = dstP.b / Math.max(1, srcP.b);

  return objs.map(o => {
    const srcTop  = o.top  || 0;
    const srcLeft = o.left || 0;
    const inBar   = srcTop >= srcBarTop;

    let newLeft, newTop;
    if (inBar) {
      // Bar area: map proportionally within bar height and photo-area width
      newTop  = Math.round(dstBarTop + ((srcTop - srcBarTop) / Math.max(1, srcP.b)) * dstP.b);
      newLeft = Math.round(dstP.l + ((srcLeft - srcP.l) / Math.max(1, srcPhotoW)) * dstPhotoW);
    } else {
      // Photo area: center-based uniform scaling
      // Each element's offset from src center is scaled uniformly, then placed relative to dst center.
      // This preserves composition proportions (no vertical stretching).
      newLeft = Math.round(dstCX + (srcLeft - srcCX) * uniform);
      newTop  = Math.round(dstCY + (srcTop  - srcCY) * uniform);
    }

    const scaled = { ...o, left: newLeft, top: newTop };

    const isTextObj = o.type === 'i-text' || o.type === 'text' || o.type === 'textbox';
    const sizeScale = inBar ? barRatio : uniform;

    // Font size (text objects)
    if (o.fontSize) {
      scaled.fontSize = Math.max(8, Math.round(o.fontSize * sizeScale));
    }
    if (isTextObj) {
      if (typeof o.strokeWidth === "number") {
        scaled.strokeWidth = o.strokeWidth > 0
          ? Math.max(0.25, +(o.strokeWidth * sizeScale).toFixed(2))
          : 0;
      }
      scaled.shadow = scaleTextShadowValue(o.shadow, sizeScale);
    }

    // scaleX / scaleY — only for NON-text objects (text already scaled via fontSize)
    if (!isTextObj) {
      if (typeof o.scaleX === "number") scaled.scaleX = +(o.scaleX * sizeScale).toFixed(4);
      if (typeof o.scaleY === "number") scaled.scaleY = +(o.scaleY * sizeScale).toFixed(4);
    }

    return scaled;
  });
}

function prepEmojiObj(fabObj, emoName) {
  fabObj._emoName = emoName;
  const orig = fabObj.toObject.bind(fabObj);
  fabObj.toObject = (props=[]) => ({ ...orig(props), _emoName: emoName });
}

function createHaloTextShadow(blur = 120) {
  if (!window.fabric) return null;
  return new window.fabric.Shadow({
    color: "rgba(255,255,255,1)",
    blur,
    offsetX: 0,
    offsetY: 0,
  });
}

const DEFAULT_TEXT_SHADOW = Object.freeze({
  color: "rgba(0,0,0,0.4)",
  blur: 8,
  offsetX: 3,
  offsetY: 3,
});

function normalizeTextShadowValue(shadow, fallback = DEFAULT_TEXT_SHADOW) {
  if (!shadow) return null;
  if (shadow === true) return { ...fallback };
  let source = shadow;
  if (typeof source?.toObject === "function") {
    try {
      source = source.toObject();
    } catch {
      source = shadow;
    }
  }
  if (!source || typeof source !== "object") return { ...fallback };
  return {
    color: typeof source.color === "string" && source.color.trim() ? source.color : fallback.color,
    blur: Number.isFinite(source.blur) ? source.blur : fallback.blur,
    offsetX: Number.isFinite(source.offsetX) ? source.offsetX : fallback.offsetX,
    offsetY: Number.isFinite(source.offsetY) ? source.offsetY : fallback.offsetY,
  };
}

function scaleTextShadowValue(shadow, factor, fallback = DEFAULT_TEXT_SHADOW) {
  const normalized = normalizeTextShadowValue(shadow, fallback);
  if (!normalized) return null;
  const safeFactor = Number.isFinite(factor) && factor > 0 ? factor : 1;
  return {
    ...normalized,
    blur: Math.max(0, +(normalized.blur * safeFactor).toFixed(2)),
    offsetX: +(normalized.offsetX * safeFactor).toFixed(2),
    offsetY: +(normalized.offsetY * safeFactor).toFixed(2),
  };
}

function createFabricTextShadow(shadow, fallback = DEFAULT_TEXT_SHADOW) {
  const normalized = normalizeTextShadowValue(shadow, fallback);
  if (!normalized || !window.fabric?.Shadow) return null;
  return new window.fabric.Shadow(normalized);
}

function getTextHaloId(id, index = 0) {
  return `${TEXT_HALO_PREFIX}${id || ""}::${index}`;
}

function getObjectHaloId(id, index = 0) {
  return `${OBJECT_HALO_PREFIX}${id || ""}::${index}`;
}

function buildDomTextEffects(layer = {}, scale = 1) {
  const effects = [];
  const shadow = normalizeTextShadowValue(layer.shadow);
  if (shadow) {
    const safeScale = Number.isFinite(scale) && scale > 0 ? scale : 1;
    effects.push(
      `${+(shadow.offsetX * safeScale).toFixed(2)}px ${+(shadow.offsetY * safeScale).toFixed(2)}px ${Math.max(0, +(shadow.blur * safeScale).toFixed(2))}px ${shadow.color}`
    );
  }
  return effects.length ? { textShadow: effects.join(", ") } : {};
}

function getDomHaloLayerStyles(scale = 1) {
  const haloScale = Math.max(0.85, scale);
  return DOM_TEXT_HALO_LAYERS.map(layer => ({
    transform: `translate(-50%,-50%) scale(${layer.scale})`,
    filter: `blur(${Math.max(6, Math.round(layer.blur * haloScale))}px)`,
  }));
}

function getFabricHaloObjects(canvas, obj) {
  if (!canvas || !obj?.id) return [];
  const textBaseId = `${TEXT_HALO_PREFIX}${obj.id || ""}`;
  const objectBaseId = `${OBJECT_HALO_PREFIX}${obj.id || ""}`;
  return canvas.getObjects().filter(item =>
    item?._haloFor === obj.id
    || String(item?.id || "").startsWith(textBaseId)
    || String(item?.id || "").startsWith(objectBaseId)
  );
}

function getFabricTextHaloObjects(canvas, obj) {
  return getFabricHaloObjects(canvas, obj);
}

function applyFabricTextHaloProps(halo, obj, config = {}) {
  const baseFontFamily = obj._uiFontFamily || obj.fontFamily || "Heebo";
  halo.set({
    text: obj.text || "",
    left: obj.left,
    top: obj.top,
    originX: obj.originX || "center",
    originY: obj.originY || "center",
    fontFamily: resolveFabricFontFamily(baseFontFamily, obj.text || ""),
    fontSize: Math.max(8, Math.round((obj.fontSize || 60) * (config.fontScale || 1))),
    fontWeight: obj.fontWeight || "normal",
    angle: obj.angle || 0,
    scaleX: (obj.scaleX ?? 1) * (config.scaleX || 1),
    scaleY: (obj.scaleY ?? 1) * (config.scaleY || 1),
    textAlign: obj.textAlign || "center",
    lineHeight: obj.lineHeight || 1.2,
    opacity: 1,
    fill: "rgba(255,255,255,1)",
    stroke: null,
    strokeWidth: 0,
    shadow: createHaloTextShadow(config.blur || 120),
  });
  refreshFabricTextGeometry(halo, halo.canvas || null);
}

function makeFabricHaloRender() {
  return function _haloRender(ctx) {
    const rX = this.width / 2;
    const rY = this.height / 2;
    const r  = Math.max(rX, rY);
    const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
    grad.addColorStop(0,    "rgba(255,255,255,0.97)");
    grad.addColorStop(0.22, "rgba(255,255,255,0.88)");
    grad.addColorStop(0.48, "rgba(255,255,255,0.55)");
    grad.addColorStop(0.72, "rgba(255,255,255,0.20)");
    grad.addColorStop(0.90, "rgba(255,255,255,0.05)");
    grad.addColorStop(1,    "rgba(255,255,255,0)");
    ctx.save();
    ctx.scale(rX / r, rY / r);
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.restore();
  };
}

function shouldUseFabricTextHalo(obj) {
  return isFabricTextGeometryObject(obj) && !obj?._emoName;
}

function getHaloBoundsForObject(obj) {
  if (!obj) return null;
  try { obj.setCoords?.(); } catch (e) {}
  let bounds = null;
  try {
    bounds = obj.getBoundingRect?.(true, true);
  } catch (e) {}
  if (!bounds || !Number.isFinite(bounds.left) || !Number.isFinite(bounds.top) || !Number.isFinite(bounds.width) || !Number.isFinite(bounds.height)) {
    const center = typeof obj.getCenterPoint === "function"
      ? obj.getCenterPoint()
      : { x: obj.left ?? 0, y: obj.top ?? 0 };
    const width = Math.max(1, Math.abs((obj.width || 0) * (obj.scaleX ?? 1)));
    const height = Math.max(1, Math.abs((obj.height || 0) * (obj.scaleY ?? 1)));
    bounds = {
      left: (center?.x ?? obj.left ?? 0) - (width / 2),
      top: (center?.y ?? obj.top ?? 0) - (height / 2),
      width,
      height,
    };
  }
  const width = Math.max(1, bounds.width || 0);
  const height = Math.max(1, bounds.height || 0);
  return {
    left: bounds.left,
    top: bounds.top,
    width,
    height,
    centerX: bounds.left + (width / 2),
    centerY: bounds.top + (height / 2),
  };
}

function applyFabricObjectHaloProps(halo, obj, config = {}) {
  const bounds = getHaloBoundsForObject(obj);
  if (!bounds) return null;
  const widthScale = Number.isFinite(config.widthScale) ? config.widthScale : (obj?._emoName ? 1.34 : 1.46);
  const heightScale = Number.isFinite(config.heightScale) ? config.heightScale : (obj?._emoName ? 1.34 : 1.46);
  const minSize = obj?._emoName ? 42 : 58;
  halo.set({
    left: bounds.centerX,
    top: bounds.centerY,
    originX: "center",
    originY: "center",
    width: Math.max(minSize, bounds.width * widthScale),
    height: Math.max(minSize, bounds.height * heightScale),
    angle: 0,
    opacity: Math.min(1, obj?.opacity ?? 1),
  });
  if (!halo._render) {
    halo._render = makeFabricHaloRender();
  }
  return bounds;
}

function syncFabricTextHaloForObject(canvas, obj) {
  if (!canvas || !obj || isHaloSystemObject(obj) || !obj.id) return null;
  const existing = getFabricHaloObjects(canvas, obj);
  const useTextHalo = shouldUseFabricTextHalo(obj);
  if (!obj.halo || (useTextHalo && !String(obj.text || "").trim())) {
    existing.forEach(item => { try { canvas.remove(item); } catch (e) {} });
    return null;
  }
  if (useTextHalo) {
    const haloId = getTextHaloId(obj.id, 0);
    let haloRect = existing.find(item => item?.id === haloId);
    const tw = (obj.width  || 100) * (obj.scaleX || 1);
    const th = (obj.height ||  50) * (obj.scaleY || 1);
    const rw = Math.max(tw * 2.52, 108);
    const rh = Math.max(th * 2.34,  72);
    if (!haloRect) {
      haloRect = new window.fabric.Rect({
        id: haloId,
        _haloFor: obj.id,
        _isTextHalo: true,
        selectable: false, evented: false, hasControls: false,
        hasBorders: false, lockMovementX: true, lockMovementY: true,
        hoverCursor: "default", excludeFromExport: false,
        fill: "transparent", stroke: null, strokeWidth: 0,
      });
      haloRect._render = makeFabricHaloRender();
      canvas.add(haloRect);
    }
    haloRect.set({
      left: obj.left,
      top:  obj.top,
      originX: obj.originX || "center",
      originY: obj.originY || "center",
      width: rw, height: rh,
      angle: obj.angle || 0,
      opacity: obj.opacity ?? 1,
    });
    existing.filter(item => item !== haloRect).forEach(item => { try { canvas.remove(item); } catch (e) {} });
    const mainIndex = canvas.getObjects().indexOf(obj);
    if (mainIndex >= 0) canvas.moveTo(haloRect, Math.max(0, mainIndex - 1));
    refreshFabricTextGeometry(obj, canvas);
    return [haloRect];
  }

  const haloId = getObjectHaloId(obj.id, 0);
  let haloRect = existing.find(item => item?.id === haloId);
  if (!haloRect) {
    haloRect = new window.fabric.Rect({
      id: haloId,
      _haloFor: obj.id,
      _isObjectHalo: true,
      selectable: false, evented: false, hasControls: false,
      hasBorders: false, lockMovementX: true, lockMovementY: true,
      hoverCursor: "default", excludeFromExport: false,
      fill: "transparent", stroke: null, strokeWidth: 0,
    });
    haloRect._render = makeFabricHaloRender();
    canvas.add(haloRect);
  }
  const bounds = applyFabricObjectHaloProps(haloRect, obj);
  if (!bounds) {
    try { canvas.remove(haloRect); } catch (e) {}
    return null;
  }
  existing.filter(item => item !== haloRect).forEach(item => { try { canvas.remove(item); } catch (e) {} });
  const mainIndex = canvas.getObjects().indexOf(obj);
  if (mainIndex >= 0) canvas.moveTo(haloRect, Math.max(0, mainIndex - 1));
  obj.setCoords?.();
  return [haloRect];
}

function removeFabricTextHaloForObject(canvas, obj) {
  if (!canvas || !obj?.id) return;
  getFabricTextHaloObjects(canvas, obj).forEach(item => {
    try { canvas.remove(item); } catch (e) {}
  });
}

function createModeState({ objs = [], textLayers = [], bg = "#ffffff", bgType = "solid", bg2 = "#c8a06e", gradAngle = 135, bgImageSrc = null, safeZone = null } = {}) {
  return {
    objs: Array.isArray(objs) ? objs : [],
    textLayers: Array.isArray(textLayers) ? textLayers.map(cloneTextLayer) : [],
    bg,
    bgType,
    bg2,
    gradAngle,
    bgImageSrc: bgImageSrc || null,
    safeZone: normalizeSafeZone(safeZone),
  };
}

function normalizeModeStateForDomText(state = {}, fallbackTextLayers = [], keepTextInObjs = false) {
  const next = createModeState(state);
  if (keepTextInObjs) {
    const hasCanvasText = Array.isArray(next.objs) && next.objs.some(isSerializedTextObject);
    if (hasCanvasText || !Array.isArray(next.textLayers) || next.textLayers.length === 0) {
      return next;
    }
    return createModeState({
      ...next,
      objs: [
        ...(Array.isArray(next.objs) ? next.objs : []),
        ...next.textLayers.map(domTextLayerToSerializedObject).filter(Boolean),
      ],
      textLayers: [],
    });
  }
  // Mobile: split IText from objs into separate DOM text layers
  const providedTextLayers = Array.isArray(next.textLayers) && next.textLayers.length
    ? next.textLayers
    : (Array.isArray(fallbackTextLayers) ? fallbackTextLayers : []);
  const { objects, textLayers: extractedTextLayers } = splitSerializedTextLayersFromObjects(next.objs || []);
  const finalTextLayers = providedTextLayers.length ? providedTextLayers : extractedTextLayers;
  return createModeState({
    ...next,
    objs: objects,
    textLayers: finalTextLayers,
  });
}

function scaleTextLayersToMode(textLayers, srcMode, dstMode) {
  if (!Array.isArray(textLayers) || !textLayers.length || srcMode === dstMode) return Array.isArray(textLayers) ? textLayers.map(cloneTextLayer) : [];
  const srcD = DIMS[srcMode], dstD = DIMS[dstMode];
  const srcP = PAD[srcMode],  dstP = PAD[dstMode];

  // Photo area bounds (mirrors scaleObjsToMode logic)
  const srcBarTop = srcD.h - srcP.b;
  const dstBarTop = dstD.h - dstP.b;
  const srcPhotoW = srcD.w - srcP.l - srcP.r;
  const srcPhotoH = srcBarTop - srcP.t;
  const dstPhotoW = dstD.w - dstP.l - dstP.r;
  const dstPhotoH = dstBarTop - dstP.t;

  // Center of photo area
  const srcCX = srcP.l + srcPhotoW / 2;
  const srcCY = srcP.t + srcPhotoH / 2;
  const dstCX = dstP.l + dstPhotoW / 2;
  const dstCY = dstP.t + dstPhotoH / 2;

  const uniform  = Math.min(dstPhotoW / Math.max(1, srcPhotoW), dstPhotoH / Math.max(1, srcPhotoH));
  const barRatio = dstP.b / Math.max(1, srcP.b);

  return textLayers.map(layer => {
    const next = cloneTextLayer(layer);
    const srcY = layer.y || 0;
    const srcX = layer.x || 0;
    const inBar = srcY >= srcBarTop;
    const scaleFactor = inBar ? barRatio : uniform;

    if (inBar) {
      next.y = Math.round(dstBarTop + ((srcY - srcBarTop) / Math.max(1, srcP.b)) * dstP.b);
      next.x = Math.round(dstP.l + ((srcX - srcP.l) / Math.max(1, srcPhotoW)) * dstPhotoW);
    } else {
      // Center-based uniform scaling (same as scaleObjsToMode)
      next.x = Math.round(dstCX + (srcX - srcCX) * uniform);
      next.y = Math.round(dstCY + (srcY - srcCY) * uniform);
    }

    next.fontSize = Math.max(8, Math.round((layer.fontSize || 24) * scaleFactor));
    if (typeof layer.strokeWidth === "number") {
      next.strokeWidth = layer.strokeWidth > 0
        ? Math.max(0.25, +(layer.strokeWidth * scaleFactor).toFixed(2))
        : 0;
    }
    next.shadow = scaleTextShadowValue(layer.shadow, scaleFactor);
    return next;
  });
}

function legacyScaleTextualCopyItem(item, srcMode, dstMode, { isTextLayer = false } = {}) {
  if (!item || srcMode === dstMode) return isTextLayer ? cloneTextLayer(item) : { ...item };
  const srcD = DIMS[srcMode], dstD = DIMS[dstMode];
  const srcP = PAD[srcMode],  dstP = PAD[dstMode];

  // Photo area bounds (same logic as scaleObjsToMode)
  const srcBarTop = srcD.h - srcP.b;
  const dstBarTop = dstD.h - dstP.b;
  const srcPhotoW = srcD.w - srcP.l - srcP.r;
  const srcPhotoH = srcBarTop - srcP.t;
  const dstPhotoW = dstD.w - dstP.l - dstP.r;
  const dstPhotoH = dstBarTop - dstP.t;

  // Center of photo area
  const srcCX = srcP.l + srcPhotoW / 2;
  const srcCY = srcP.t + srcPhotoH / 2;
  const dstCX = dstP.l + dstPhotoW / 2;
  const dstCY = dstP.t + dstPhotoH / 2;

  const uniform  = Math.min(dstPhotoW / Math.max(1, srcPhotoW), dstPhotoH / Math.max(1, srcPhotoH));
  const barRatio = dstP.b / Math.max(1, srcP.b);

  const srcTop  = isTextLayer ? (typeof item?.y === "number" ? item.y : 0) : (item.top || 0);
  const srcLeft = isTextLayer ? (typeof item?.x === "number" ? item.x : 0) : (item.left || 0);
  const inBar   = srcTop >= srcBarTop;

  let newLeft, newTop;
  if (inBar) {
    // Bar area: proportional within bar height, photo-area-relative X
    newTop  = Math.round(dstBarTop + ((srcTop - srcBarTop) / Math.max(1, srcP.b)) * dstP.b);
    newLeft = Math.round(dstP.l + ((srcLeft - srcP.l) / Math.max(1, srcPhotoW)) * dstPhotoW);
  } else {
    // Photo area: center-based uniform scaling (preserves composition)
    newLeft = Math.round(dstCX + (srcLeft - srcCX) * uniform);
    newTop  = Math.round(dstCY + (srcTop  - srcCY) * uniform);
  }

  const next = isTextLayer ? cloneTextLayer(item) : { ...item };
  if (isTextLayer) {
    next.x = newLeft;
    next.y = newTop;
  } else {
    next.left = newLeft;
    next.top  = newTop;
  }
  // Scale fontSize only (scaleX/scaleY preserve user's manual adjustments)
  const scaleFactor = inBar ? barRatio : uniform;
  if (item.fontSize) next.fontSize = Math.max(8, Math.round(item.fontSize * scaleFactor));
  if (typeof item.strokeWidth === "number") {
    next.strokeWidth = item.strokeWidth > 0
      ? Math.max(0.25, +(item.strokeWidth * scaleFactor).toFixed(2))
      : 0;
  }
  next.shadow = scaleTextShadowValue(item.shadow, scaleFactor);
  return next;
}

function getModeRects(mode) {
  const dims = DIMS[mode];
  const pad = PAD[mode];
  const photoTop = pad.t;
  const photoLeft = pad.l;
  const photoBottom = dims.h - pad.b;
  const photoRight = dims.w - pad.r;
  return {
    dims,
    pad,
    canvas: { left: 0, top: 0, right: dims.w, bottom: dims.h, width: dims.w, height: dims.h, centerX: dims.w / 2, centerY: dims.h / 2 },
    photo: {
      left: photoLeft,
      top: photoTop,
      right: photoRight,
      bottom: photoBottom,
      width: photoRight - photoLeft,
      height: photoBottom - photoTop,
      centerX: photoLeft + (photoRight - photoLeft) / 2,
      centerY: photoTop + (photoBottom - photoTop) / 2,
    },
    bottomBand: {
      left: 0,
      top: photoBottom,
      right: dims.w,
      bottom: dims.h,
      width: dims.w,
      height: pad.b,
      centerX: dims.w / 2,
      centerY: photoBottom + pad.b / 2,
    },
  };
}

function approxCopyItemSize(item, { isTextLayer = false } = {}) {
  const sx = Math.abs(item?.scaleX ?? 1) || 1;
  const sy = Math.abs(item?.scaleY ?? 1) || 1;
  if (!isTextLayer && (item?.type === "image" || item?.type === "rect" || item?.type === "circle" || item?.type === "group")) {
    const width = ((item?.width || 0) * sx) || 0;
    const height = ((item?.height || 0) * sy) || 0;
    if (width > 0 && height > 0) {
      return { width, height };
    }
  }
  const text = String(item?.text || "");
  const fontSize = Math.max(12, item?.fontSize || (isTextLayer ? 24 : 36));
  const lines = Math.max(1, text.split(/\r?\n/).length);
  const longest = text.split(/\r?\n/).reduce((m, line) => Math.max(m, line.length), 0) || 1;
  return {
    width: Math.max(12, fontSize * Math.max(1.1, longest * 0.55) * sx),
    height: Math.max(12, fontSize * Math.max(1, lines * (item?.lineHeight || 1.2)) * sy),
  };
}

function getCopyItemCenter(item, { isTextLayer = false } = {}) {
  if (isTextLayer) {
    return {
      x: typeof item?.x === "number" ? item.x : 0,
      y: typeof item?.y === "number" ? item.y : 0,
    };
  }
  const originX = item?.originX || "left";
  const originY = item?.originY || "top";
  const { width, height } = approxCopyItemSize(item);
  const left = typeof item?.left === "number" ? item.left : 0;
  const top = typeof item?.top === "number" ? item.top : 0;
  return {
    x: originX === "center" ? left : originX === "right" ? left - width / 2 : left + width / 2,
    y: originY === "center" ? top : originY === "bottom" ? top - height / 2 : top + height / 2,
  };
}

function getCopyItemBox(item, options = {}) {
  const center = getCopyItemCenter(item, options);
  const { width, height } = approxCopyItemSize(item, options);
  return {
    left: center.x - width / 2,
    top: center.y - height / 2,
    right: center.x + width / 2,
    bottom: center.y + height / 2,
    width,
    height,
    centerX: center.x,
    centerY: center.y,
  };
}

function isDecorativeCopyItem(item, { isTextLayer = false } = {}) {
  if (isTextLayer) return false;
  return !!(
    item && (
      item.type === "image"
      || item._emoName
      || item._elementName
      || String(item?.id || "").startsWith("invite-decoration")
      || looksLikeCenterDecorId(item?.id)
      || (item.type === "text" && !looksLikeTextLayoutId(item?.id))
    )
  );
}

function buildDecorAnchor(prefix, left, right, top, bottom) {
  if (left && top) return `${prefix}-top-left`;
  if (right && top) return `${prefix}-top-right`;
  if (left && bottom) return `${prefix}-bottom-left`;
  if (right && bottom) return `${prefix}-bottom-right`;
  if (left) return `${prefix}-left`;
  if (right) return `${prefix}-right`;
  if (top) return `${prefix}-top-center`;
  if (bottom) return `${prefix}-bottom-center`;
  return `${prefix}-center`;
}

function pickDecorAnchor(rects, box, flags) {
  const {
    nearCanvasLeft,
    nearCanvasRight,
    nearCanvasTop,
    nearCanvasBottom,
    nearPhotoLeft,
    nearPhotoRight,
    nearPhotoTop,
    nearPhotoBottom,
    outsidePhotoFrame,
  } = flags;
  const canvasScore = [nearCanvasLeft, nearCanvasRight, nearCanvasTop, nearCanvasBottom].filter(Boolean).length;
  const photoScore = [nearPhotoLeft, nearPhotoRight, nearPhotoTop, nearPhotoBottom].filter(Boolean).length;
  const useCanvas = outsidePhotoFrame || canvasScore > photoScore;
  if (useCanvas && canvasScore > 0) {
    return buildDecorAnchor("canvas", nearCanvasLeft, nearCanvasRight, nearCanvasTop, nearCanvasBottom);
  }
  if (photoScore > 0) {
    return buildDecorAnchor("photo", nearPhotoLeft, nearPhotoRight, nearPhotoTop, nearPhotoBottom);
  }
  const fallbackLeft = box.centerX < rects.dims.w / 2;
  const fallbackTop = box.centerY < rects.dims.h / 2;
  return buildDecorAnchor("canvas", fallbackLeft, !fallbackLeft, fallbackTop, !fallbackTop);
}

function classifyCopyItemRole(item, srcMode, { isTextLayer = false } = {}) {
  const rects = getModeRects(srcMode);
  const box = getCopyItemBox(item, { isTextLayer });
  const decorative = isDecorativeCopyItem(item, { isTextLayer });
  const textual = isTextLayer || isArrangedTextLikeObject(item);
  const inBottomBand = box.centerY >= rects.bottomBand.top - Math.min(36, rects.pad.b * 0.14);
  const nearCenter = Math.abs(box.centerX - rects.dims.w / 2) <= rects.dims.w * 0.14;
  const nearCanvasLeft = Math.abs(box.left - rects.canvas.left) <= rects.dims.w * 0.08;
  const nearCanvasRight = Math.abs(rects.canvas.right - box.right) <= rects.dims.w * 0.08;
  const nearCanvasTop = Math.abs(box.top - rects.canvas.top) <= rects.dims.h * 0.08;
  const nearCanvasBottom = Math.abs(rects.canvas.bottom - box.bottom) <= rects.dims.h * 0.08;
  const nearPhotoLeft = Math.abs(box.left - rects.photo.left) <= rects.photo.width * 0.14;
  const nearPhotoRight = Math.abs(rects.photo.right - box.right) <= rects.photo.width * 0.14;
  const nearPhotoTop = Math.abs(box.top - rects.photo.top) <= rects.photo.height * 0.14;
  const nearPhotoBottom = Math.abs(rects.photo.bottom - box.bottom) <= rects.photo.height * 0.14;
  const outsidePhotoFrame = box.left < rects.photo.left || box.right > rects.photo.right || box.top < rects.photo.top || box.bottom > rects.photo.bottom;
  const smallDecorative = decorative && Math.max(box.width, box.height) <= Math.min(rects.photo.width, rects.photo.height) * 0.16;
  const elongatedDecorative = decorative && (
    box.width >= box.height * 1.35
    || box.height >= box.width * 1.35
    || box.width >= rects.photo.width * 0.18
    || box.height >= rects.photo.height * 0.18
  );
  const canvasCornerish = (nearCanvasLeft || nearCanvasRight) && (nearCanvasTop || nearCanvasBottom);
  const photoCornerish = (nearPhotoLeft || nearPhotoRight) && (nearPhotoTop || nearPhotoBottom);
  const canvasEdgeish = nearCanvasLeft || nearCanvasRight || nearCanvasTop || nearCanvasBottom;
  const photoEdgeish = nearPhotoLeft || nearPhotoRight || nearPhotoTop || nearPhotoBottom;
  const decorAnchor = decorative ? pickDecorAnchor(rects, box, {
    nearCanvasLeft,
    nearCanvasRight,
    nearCanvasTop,
    nearCanvasBottom,
    nearPhotoLeft,
    nearPhotoRight,
    nearPhotoTop,
    nearPhotoBottom,
    outsidePhotoFrame,
  }) : "free";
  const overflow = decorative ? {
    left: box.left < rects.canvas.left,
    top: box.top < rects.canvas.top,
    right: box.right > rects.canvas.right,
    bottom: box.bottom > rects.canvas.bottom,
  } : { left: false, top: false, right: false, bottom: false };

  if (textual && inBottomBand) {
    return {
      role: isArrangedDateLikeObject(item) ? "bottom_text_secondary" : ((item.fontSize || 0) >= 48 ? "bottom_text_primary" : "bottom_text_secondary"),
      anchor: nearCenter ? "bottom-center" : box.centerX < rects.dims.w / 2 ? "bottom-left-band" : "bottom-right-band",
      box,
      centerAligned: nearCenter || (isTextLayer ? String(item.textAlign || "").toLowerCase() === "center" : item.originX === "center"),
      overflow,
    };
  }

  if (decorative && smallDecorative && (canvasCornerish || photoCornerish)) {
    return {
      role: "corner_accent",
      anchor: decorAnchor,
      box,
      centerAligned: false,
      overflow,
    };
  }

  if (decorative && nearCenter && nearPhotoTop) {
    return {
      role: "top_decoration",
      anchor: box.top < rects.photo.top ? "canvas-top-center" : "photo-top-center",
      box,
      centerAligned: true,
      overflow,
    };
  }

  if (decorative && !smallDecorative && (canvasCornerish || photoCornerish)) {
    return {
      role: elongatedDecorative ? "edge_hugging_decoration" : "corner_decoration",
      anchor: decorAnchor,
      box,
      centerAligned: false,
      overflow,
    };
  }

  if (decorative && !smallDecorative && (outsidePhotoFrame || canvasEdgeish || photoEdgeish)) {
    return {
      role: "edge_hugging_decoration",
      anchor: decorAnchor,
      box,
      centerAligned: false,
      overflow,
    };
  }

  if (decorative && inBottomBand) {
    return {
      role: "bottom_band_decoration",
      anchor: box.centerX < rects.dims.w * 0.34 ? "canvas-bottom-left" : box.centerX > rects.dims.w * 0.66 ? "canvas-bottom-right" : "bottom-center",
      box,
      centerAligned: false,
      overflow,
    };
  }

  if (decorative && looksLikeCenterDecorId(item?.id)) {
    return {
      role: "center_object",
      anchor: "center",
      box,
      centerAligned: true,
      overflow,
    };
  }

  if (textual && nearCenter) {
    return {
      role: "center_object",
      anchor: "center",
      box,
      centerAligned: true,
      overflow,
    };
  }

  return {
    role: decorative && outsidePhotoFrame ? "edge_hugging_decoration" : "free_object",
    anchor: decorative && outsidePhotoFrame
      ? (nearCanvasLeft ? "canvas-left" : nearCanvasRight ? "canvas-right" : nearCanvasTop ? "canvas-top-center" : nearCanvasBottom ? "canvas-bottom-center" : "free")
      : "free",
    box,
    centerAligned: false,
    overflow,
  };
}

function computeCopyScaleFactor(item, role, srcMode, dstMode) {
  const src = getModeRects(srcMode);
  const dst = getModeRects(dstMode);
  const canvasUniform = Math.min(dst.dims.w / Math.max(1, src.dims.w), dst.dims.h / Math.max(1, src.dims.h));
  const photoUniform = Math.min(dst.photo.width / Math.max(1, src.photo.width), dst.photo.height / Math.max(1, src.photo.height));
  const widthRatio = dst.photo.width / Math.max(1, src.photo.width);
  const heightRatio = dst.photo.height / Math.max(1, src.photo.height);
  const canvasWidthRatio = dst.dims.w / Math.max(1, src.dims.w);
  const box = getCopyItemBox(item);
  const aspect = box.width / Math.max(1, box.height);
  if (role === "bottom_text_primary") return Math.max(canvasWidthRatio, dst.bottomBand.height / Math.max(1, src.bottomBand.height) * 1.1);
  if (role === "bottom_text_secondary") return Math.max(canvasWidthRatio * 0.98, dst.bottomBand.height / Math.max(1, src.bottomBand.height) * 1.05);
  if (role === "corner_accent") return canvasWidthRatio;
  if (role === "bottom_band_decoration" || role === "corner_decoration" || role === "top_decoration" || role === "edge_hugging_decoration") {
    if (aspect >= 1.12) return widthRatio;
    if (aspect <= 0.88) return heightRatio;
    return Math.max(photoUniform, Math.sqrt(widthRatio * heightRatio));
  }
  return canvasUniform;
}

function scaleCopyInset(value, ratio) {
  return value * ratio;
}

function scaleCopyItemVisuals(item, factor, { isTextLayer = false } = {}) {
  if (isTextLayer) {
    const next = cloneTextLayer(item);
    next.fontSize = Math.max(8, Math.round((item.fontSize || 24) * factor));
    next.strokeWidth = item.strokeWidth > 0
      ? Math.max(0.25, +(item.strokeWidth * factor).toFixed(2))
      : 0;
    next.shadow = scaleTextShadowValue(item.shadow, factor);
    // Don't scale scaleX/scaleY for text layers — fontSize handles sizing
    return next;
  }
  const next = { ...item };
  const isText = item.type === 'i-text' || item.type === 'text' || item.type === 'textbox';
  if (item.fontSize) next.fontSize = Math.max(8, Math.round(item.fontSize * factor));
  if (isText && typeof item.strokeWidth === "number") {
    next.strokeWidth = item.strokeWidth > 0
      ? Math.max(0.25, +(item.strokeWidth * factor).toFixed(2))
      : 0;
  }
  if (isText) {
    next.shadow = scaleTextShadowValue(item.shadow, factor);
  }
  // For text objects, fontSize handles sizing; for non-text, scale transform handles it
  if (!isText) {
    if (typeof item.scaleX === "number") next.scaleX = +(item.scaleX * factor).toFixed(4);
    if (typeof item.scaleY === "number") next.scaleY = +(item.scaleY * factor).toFixed(4);
  }
  return next;
}

function placeCopyItemByCenter(item, centerX, centerY, { isTextLayer = false } = {}) {
  if (isTextLayer) {
    item.x = Math.round(centerX);
    item.y = Math.round(centerY);
    return item;
  }
  const originX = item.originX || "left";
  const originY = item.originY || "top";
  const { width, height } = approxCopyItemSize(item);
  if (originX === "center") item.left = Math.round(centerX);
  else if (originX === "right") item.left = Math.round(centerX + width / 2);
  else item.left = Math.round(centerX - width / 2);
  if (originY === "center") item.top = Math.round(centerY);
  else if (originY === "bottom") item.top = Math.round(centerY + height / 2);
  else item.top = Math.round(centerY - height / 2);
  return item;
}

function getAnchorCenterDistances(box, rect, anchor) {
  if (anchor.endsWith("left")) {
    return { x: box.centerX - rect.left, y: null };
  }
  if (anchor.endsWith("right")) {
    return { x: rect.right - box.centerX, y: null };
  }
  return { x: box.centerX - rect.centerX, y: null };
}

function getAnchorVerticalDistances(box, rect, anchor) {
  if (anchor.includes("top")) {
    return { y: box.centerY - rect.top };
  }
  if (anchor.includes("bottom")) {
    return { y: rect.bottom - box.centerY };
  }
  return { y: box.centerY - rect.centerY };
}

function getSignedRectInsets(box, rect) {
  return {
    left: box.left - rect.left,
    right: rect.right - box.right,
    top: box.top - rect.top,
    bottom: rect.bottom - box.bottom,
  };
}

function resolveDecorativeCenterByEdges(meta, nextBox, srcRect, dstRect, ratioX, ratioY) {
  const insets = getSignedRectInsets(meta.box, srcRect);
  const defaultCenterX = dstRect.centerX + (meta.box.centerX - srcRect.centerX) * ratioX;
  const defaultCenterY = dstRect.centerY + (meta.box.centerY - srcRect.centerY) * ratioY;
  const xThreshold = srcRect.width * 0.18;
  const yThreshold = srcRect.height * 0.18;
  const anchorLeft = meta.anchor.endsWith("left");
  const anchorRight = meta.anchor.endsWith("right");
  const anchorTop = meta.anchor.includes("top");
  const anchorBottom = meta.anchor.includes("bottom");
  const closerToLeft = insets.left <= insets.right;
  const closerToTop = insets.top <= insets.bottom;
  const preserveLeft = anchorLeft || (!anchorRight && insets.left <= xThreshold && closerToLeft);
  const preserveRight = anchorRight || (!anchorLeft && insets.right <= xThreshold && !closerToLeft);
  const preserveTop = anchorTop || (!anchorBottom && insets.top <= yThreshold && closerToTop);
  const preserveBottom = anchorBottom || (!anchorTop && insets.bottom <= yThreshold && !closerToTop);

  let centerX = defaultCenterX;
  if (preserveLeft) {
    const nextLeft = dstRect.left + scaleCopyInset(insets.left, ratioX);
    centerX = nextLeft + nextBox.width / 2;
  } else if (preserveRight) {
    const nextRight = dstRect.right - scaleCopyInset(insets.right, ratioX);
    centerX = nextRight - nextBox.width / 2;
  }

  let centerY = defaultCenterY;
  if (preserveTop) {
    const nextTop = dstRect.top + scaleCopyInset(insets.top, ratioY);
    centerY = nextTop + nextBox.height / 2;
  } else if (preserveBottom) {
    const nextBottom = dstRect.bottom - scaleCopyInset(insets.bottom, ratioY);
    centerY = nextBottom - nextBox.height / 2;
  }

  return { centerX, centerY };
}

function transformCopyItemV2(item, srcMode, dstMode, options = {}) {
  const meta = classifyCopyItemRole(item, srcMode, options);
  const src = getModeRects(srcMode);
  const dst = getModeRects(dstMode);
  const factor = computeCopyScaleFactor(item, meta.role, srcMode, dstMode);
  const next = scaleCopyItemVisuals(item, factor, options);
  const nextBox = getCopyItemBox(next, options);
  const srcRect = meta.anchor.startsWith("photo-")
    ? src.photo
    : (meta.anchor === "bottom-center" || meta.anchor.startsWith("bottom-") ? src.bottomBand : src.canvas);
  const dstRect = meta.anchor.startsWith("photo-")
    ? dst.photo
    : (meta.anchor === "bottom-center" || meta.anchor.startsWith("bottom-") ? dst.bottomBand : dst.canvas);
  const ratioX = dstRect.width / Math.max(1, srcRect.width);
  const ratioY = dstRect.height / Math.max(1, srcRect.height);

  if (meta.role === "free_object") {
    const relX = meta.box.centerX / Math.max(1, src.dims.w);
    const relY = meta.box.centerY / Math.max(1, src.dims.h);
    return placeCopyItemByCenter(next, relX * dst.dims.w, relY * dst.dims.h, options);
  }

  const decorativeRoles = new Set([
    "corner_accent",
    "corner_decoration",
    "edge_hugging_decoration",
    "top_decoration",
    "bottom_band_decoration",
  ]);
  if (decorativeRoles.has(meta.role)) {
    const { centerX, centerY } = resolveDecorativeCenterByEdges(meta, nextBox, srcRect, dstRect, ratioX, ratioY);
    return placeCopyItemByCenter(next, centerX, centerY, options);
  }

  const sourceCenterXDist = getAnchorCenterDistances(meta.box, srcRect, meta.anchor).x;
  const sourceCenterYDist = getAnchorVerticalDistances(meta.box, srcRect, meta.anchor).y;

  let centerX;
  if (meta.anchor.endsWith("left")) {
    centerX = dstRect.left + scaleCopyInset(sourceCenterXDist, ratioX);
  } else if (meta.anchor.endsWith("right")) {
    centerX = dstRect.right - scaleCopyInset(sourceCenterXDist, ratioX);
  } else {
    centerX = dstRect.centerX + sourceCenterXDist * ratioX;
  }

  let centerY;
  if (meta.anchor.includes("top")) {
    centerY = dstRect.top + scaleCopyInset(sourceCenterYDist, ratioY);
  } else if (meta.anchor.includes("bottom")) {
    centerY = dstRect.bottom - scaleCopyInset(sourceCenterYDist, ratioY);
  } else {
    centerY = dstRect.centerY + sourceCenterYDist * ratioY;
  }

  if ((meta.role === "bottom_text_primary" || meta.role === "bottom_text_secondary") && meta.centerAligned) {
    centerX = dst.bottomBand.centerX;
  }

  return placeCopyItemByCenter(next, centerX, centerY, options);
}

function rebalanceBottomTextGroupV2(items, entries, srcMode, dstMode, options = {}) {
  if (!entries.length) return items;
  const src = getModeRects(srcMode);
  const dst = getModeRects(dstMode);
  const sortedEntries = entries
    .slice()
    .sort((a, b) => a.meta.box.top - b.meta.box.top || a.meta.box.centerX - b.meta.box.centerX);
  const srcBoxes = sortedEntries.map(entry => entry.meta.box);
  const srcGroup = {
    left: Math.min(...srcBoxes.map(b => b.left)),
    right: Math.max(...srcBoxes.map(b => b.right)),
    top: Math.min(...srcBoxes.map(b => b.top)),
    bottom: Math.max(...srcBoxes.map(b => b.bottom)),
  };
  srcGroup.width = srcGroup.right - srcGroup.left;
  srcGroup.height = srcGroup.bottom - srcGroup.top;
  const nextItems = items.slice();
  const currentPrimaryEntries = sortedEntries.filter(entry => entry.meta.role === "bottom_text_primary");
  const sourcePrimaryEntry = (currentPrimaryEntries.length ? currentPrimaryEntries : sortedEntries)[0];
  const sourcePrimaryWidth = Math.max(1, sourcePrimaryEntry?.meta?.box?.width || srcGroup.width);
  const currentPrimaryWidth = Math.max(
    1,
    ...(currentPrimaryEntries.length ? currentPrimaryEntries : sortedEntries).map(entry => getCopyItemBox(nextItems[entry.index], options).width)
  );
  const sourcePrimaryWidthRatio = sourcePrimaryWidth / Math.max(1, src.photo.width);
  const desiredPrimaryWidth = Math.min(
    dst.photo.width * 0.52,
    Math.max(dst.photo.width * 0.34, sourcePrimaryWidthRatio * dst.photo.width * 1.05)
  );
  const widthBoost = desiredPrimaryWidth / Math.max(1, currentPrimaryWidth);

  if (Math.abs(widthBoost - 1) > 0.04) {
    sortedEntries.forEach((entry) => {
      nextItems[entry.index] = scaleCopyItemVisuals(nextItems[entry.index], widthBoost, options);
    });
  }

  const centerAligned = sortedEntries.some(entry => entry.meta.centerAligned);
  const desiredCenterX = centerAligned ? dst.bottomBand.centerX : (srcGroup.left + srcGroup.width / 2) / Math.max(1, src.dims.w) * dst.dims.w;
  const primaryEntries = sortedEntries.filter(entry => entry.meta.role === "bottom_text_primary");
  const secondaryEntries = sortedEntries.filter(entry => entry.meta.role === "bottom_text_secondary");
  const primaryCenters = [];

  if (primaryEntries.length) {
    const primaryTotalWidth = primaryEntries.reduce((sum, entry) => sum + getCopyItemBox(nextItems[entry.index], options).width, 0);
    const primaryGap = primaryEntries.length > 1 ? Math.max(12, dst.photo.width * 0.018) : 0;
    const primaryBlockWidth = primaryTotalWidth + primaryGap * Math.max(0, primaryEntries.length - 1);
    let cursorX = desiredCenterX - primaryBlockWidth / 2;
    const primaryCenterY = dst.bottomBand.top + dst.bottomBand.height * (dstMode === "portrait" ? 0.33 : 0.39);
    primaryEntries.forEach((entry) => {
      const item = nextItems[entry.index];
      const box = getCopyItemBox(item, options);
      const cx = cursorX + box.width / 2;
      nextItems[entry.index] = placeCopyItemByCenter(item, cx, primaryCenterY, options);
      primaryCenters.push(getCopyItemBox(nextItems[entry.index], options));
      cursorX += box.width + primaryGap;
    });
  }

  const primaryBottom = primaryCenters.length
    ? Math.max(...primaryCenters.map(box => box.bottom))
    : dst.bottomBand.top + dst.bottomBand.height * 0.34;

  let secondaryCursorY = primaryBottom + Math.max(10, dst.bottomBand.height * 0.04);
  secondaryEntries.forEach((entry, idx) => {
    const item = nextItems[entry.index];
    const box = getCopyItemBox(item, options);
    const centerY = secondaryCursorY + box.height / 2;
    const offsetX = centerAligned ? 0 : (entry.meta.box.centerX - (srcGroup.left + srcGroup.width / 2)) * (dst.photo.width / Math.max(1, src.photo.width));
    nextItems[entry.index] = placeCopyItemByCenter(item, desiredCenterX + offsetX, centerY, options);
    const placed = getCopyItemBox(nextItems[entry.index], options);
    secondaryCursorY = placed.bottom + Math.max(8, dst.bottomBand.height * 0.032);
  });

  const allPlacedBoxes = sortedEntries.map(entry => getCopyItemBox(nextItems[entry.index], options));
  const groupBottom = Math.max(...allPlacedBoxes.map(box => box.bottom));
  const maxBottom = dst.bottomBand.bottom - Math.max(10, dst.bottomBand.height * 0.08);
  if (groupBottom > maxBottom) {
    const shiftUp = groupBottom - maxBottom;
    sortedEntries.forEach((entry) => {
      const item = nextItems[entry.index];
      const box = getCopyItemBox(item, options);
      nextItems[entry.index] = placeCopyItemByCenter(item, box.centerX, box.centerY - shiftUp, options);
    });
  }

  return nextItems;
}

function copyItemsToModeWithLayoutV2(items, srcMode, dstMode, options = {}) {
  if (!Array.isArray(items) || !items.length || srcMode === dstMode) {
    return Array.isArray(items)
      ? items.map(item => (options.isTextLayer ? cloneTextLayer(item) : ({ ...item })))
      : [];
  }
  const transformed = [];
  const bottomTextEntries = [];
  items.forEach((item, index) => {
    const textualLike = options.isTextLayer || (isArrangedTextLikeObject(item) && !isDecorativeCopyItem(item, options));
    if (textualLike) {
      try {
        const next = legacyScaleTextualCopyItem(item, srcMode, dstMode, options);
        transformed.push(options.isTextLayer ? cloneTextLayer(next) : (normalizeSerializedObject(next) || { ...item }));
      } catch (err) {
        const fallback = options.isTextLayer
          ? cloneTextLayer(scaleTextLayersToMode([item], srcMode, dstMode)[0])
          : (normalizeSerializedObject(scaleObjsToMode([item], srcMode, dstMode)[0]) || { ...item });
        transformed.push(fallback);
      }
      return;
    }
    try {
      const meta = classifyCopyItemRole(item, srcMode, options);
      const next = transformCopyItemV2(item, srcMode, dstMode, options);
      transformed.push(options.isTextLayer ? cloneTextLayer(next) : (normalizeSerializedObject(next) || { ...item }));
      if (meta.role === "bottom_text_primary" || meta.role === "bottom_text_secondary") {
        bottomTextEntries.push({ index, meta, source: item });
      }
    } catch (err) {
      const fallback = options.isTextLayer
        ? cloneTextLayer(scaleTextLayersToMode([item], srcMode, dstMode)[0])
        : (normalizeSerializedObject(scaleObjsToMode([item], srcMode, dstMode)[0]) || { ...item });
      transformed.push(fallback);
    }
  });
  return rebalanceBottomTextGroupV2(transformed, bottomTextEntries, srcMode, dstMode, options);
}

function copyObjsToModeV2(objs, srcMode, dstMode) {
  return copyItemsToModeWithLayoutV2(objs, srcMode, dstMode, { isTextLayer: false }).map(normalizeSerializedObject).filter(Boolean);
}

function copyTextLayersToModeV2(textLayers, srcMode, dstMode) {
  // Mobile DOM text layers behaved better with the older bottom-band aware
  // scaler than with the newer object-role copy pipeline. Keep decorations on
  // the V2 engine, but let textLayers follow the legacy text layout copy.
  return scaleTextLayersToMode(textLayers, srcMode, dstMode).map(cloneTextLayer);
}

function normalizeSerializedObject(obj) {
  if (!obj || typeof obj !== "object") return null;
  const next = { ...obj };
  if (typeof next.src === "string") {
    next.src = normalizeLocalAppAssetUrl(next.src);
  }
  if (typeof next.bgImageSrc === "string") {
    next.bgImageSrc = normalizeLocalAppAssetUrl(next.bgImageSrc);
  }
  if (typeof next.frameSrc === "string") {
    next.frameSrc = normalizeLocalAppAssetUrl(next.frameSrc);
  }
  const normalizedTextBaseline = normalizeCanvasTextBaseline(next.textBaseline);
  if (normalizedTextBaseline) next.textBaseline = normalizedTextBaseline;
  else delete next.textBaseline;
  if ((next.type === "i-text" || next.type === "text" || next.type === "textbox") && typeof next.text !== "string") {
    next.text = String(next.text ?? "");
  }
  if ((next.type === "i-text" || next.type === "text" || next.type === "textbox") && typeof next.text === "string") {
    next.text = normalizeTemplateScalarString(next.text);
  }
  if ((next.type === "i-text" || next.type === "text" || next.type === "textbox") && (next.styles == null || typeof next.styles !== "object")) {
    next.styles = {};
  }
  if (next.type === "i-text" || next.type === "text" || next.type === "textbox") {
    next.shadow = normalizeTextShadowValue(next.shadow);
  }
  if ("halo" in next) {
    next.halo = !!next.halo;
  }
  return next;
}

function normalizeSerializedObjects(objs) {
  if (!Array.isArray(objs)) return [];
  return objs.map(normalizeSerializedObject).filter(Boolean);
}

function sanitizeFabricTextObjectForCanvas(obj) {
  if (!obj || typeof obj !== "object") return obj;
  if (obj.type !== "i-text" && obj.type !== "text" && obj.type !== "textbox") return obj;
  const next = { ...obj };
  delete next.direction;
  delete next.textBaseline;
  delete next.width;
  delete next.height;
  if (next.styles == null || typeof next.styles !== "object") {
    next.styles = {};
  }
  return next;
}

const LOCAL_APP_ASSET_URL_RE = /^(?:https?:\/\/(?:127\.0\.0\.1|0\.0\.0\.0|localhost|192\.168(?:\.\d{1,3}){2}|10(?:\.\d{1,3}){3}|172\.(?:1[6-9]|2\d|3[0-1])(?:\.\d{1,3}){2})(?::\d+)?)(\/(?:elements-14\.3|bg-images|assets)\/[^?#]+)([?#].*)?$/i;
const LOCAL_APP_ASSET_RELATIVE_RE = /^(?:\.\/)?((?:elements-14\.3|bg-images|assets)\/.+)$/i;
const VALID_CANVAS_TEXT_BASELINES = new Set(["top", "hanging", "middle", "alphabetic", "ideographic", "bottom"]);

function normalizeLocalAppAssetUrl(value) {
  if (typeof value !== "string") return value;
  const raw = value.trim();
  if (!raw) return value;

  function resolveSegmentPath(segPath) {
    const slashIdx = segPath.indexOf("/");
    if (slashIdx === -1) return null;
    const segment = segPath.slice(0, slashIdx).toLowerCase();
    const filename = segPath.slice(slashIdx + 1).replace(/\.(png|jpg)$/i, "");
    if (segment === "elements-14.3") return ICON_ASSET_SRC_BY_ID.get(filename) ?? ICON_ASSET_SRC_BY_ID_CI.get(filename.toLowerCase()) ?? null;
    if (segment === "bg-images") return (BG_IMAGE_BY_NAME.get(filename) ?? BG_IMAGE_BY_NAME_CI.get(filename.toLowerCase()))?.src ?? null;
    return null;
  }

  const relativeMatch = raw.match(LOCAL_APP_ASSET_RELATIVE_RE);
  if (relativeMatch) return resolveSegmentPath(relativeMatch[1]) ?? `/${relativeMatch[1]}`;

  const rootMatch = raw.match(/^\/((?:elements-14\.3|bg-images|assets)\/.+)$/i);
  if (rootMatch) return resolveSegmentPath(rootMatch[1]) ?? raw;

  const absoluteMatch = raw.match(LOCAL_APP_ASSET_URL_RE);
  if (absoluteMatch) {
    const pathPart = (absoluteMatch[2] || "").replace(/^\//, "");
    return resolveSegmentPath(pathPart) ?? `${absoluteMatch[1]}${absoluteMatch[2] || ""}`;
  }
  return value;
}

function normalizeCanvasTextBaseline(value) {
  if (typeof value !== "string") return "";
  const raw = value.trim().toLowerCase();
  if (!raw) return "";
  if (raw === "alphabetical") return "alphabetic";
  return VALID_CANVAS_TEXT_BASELINES.has(raw) ? raw : "";
}

const CP1252_UNICODE_TO_BYTE = {
  0x20ac: 0x80,
  0x201a: 0x82,
  0x0192: 0x83,
  0x201e: 0x84,
  0x2026: 0x85,
  0x2020: 0x86,
  0x2021: 0x87,
  0x02c6: 0x88,
  0x2030: 0x89,
  0x0160: 0x8a,
  0x2039: 0x8b,
  0x0152: 0x8c,
  0x017d: 0x8e,
  0x2018: 0x91,
  0x2019: 0x92,
  0x201c: 0x93,
  0x201d: 0x94,
  0x2022: 0x95,
  0x2013: 0x96,
  0x2014: 0x97,
  0x02dc: 0x98,
  0x2122: 0x99,
  0x0161: 0x9a,
  0x203a: 0x9b,
  0x0153: 0x9c,
  0x017e: 0x9e,
  0x0178: 0x9f,
};

const MOJIBAKE_SUSPICIOUS_CHARS = /[\u00C2\u00C3\u00D7\u00E2\u00EF\u0152\u0153\u02DC\u2018\u2019\u201C\u201D\u2122]/;

function repairMojibakeString(value) {
  if (typeof value !== "string" || !MOJIBAKE_SUSPICIOUS_CHARS.test(value)) return value;
  try {
    const bytes = Uint8Array.from(Array.from(value), (ch) => {
      const code = ch.charCodeAt(0);
      if (code <= 0xff) return code;
      return CP1252_UNICODE_TO_BYTE[code] ?? 0x3f;
    });
    const repaired = new TextDecoder("utf-8", { fatal: false }).decode(bytes);
    if (!repaired || repaired.includes("\uFFFD")) return value;
    const originalMarkers = (value.match(MOJIBAKE_SUSPICIOUS_CHARS) || []).length;
    const repairedMarkers = (repaired.match(MOJIBAKE_SUSPICIOUS_CHARS) || []).length;
    if (repairedMarkers >= originalMarkers) return value;
    if (/[א-ת]/.test(repaired) || /[♡♥✦•]/.test(repaired) || /^(\d{2}\.\d{2}\.\d{4})$/.test(repaired) || repaired.includes("&")) {
      return repaired;
    }
    return value;
  } catch (e) {
    return value;
  }
}

function normalizeTemplateScalarString(value) {
  if (typeof value !== "string") return value;
  return normalizeLocalAppAssetUrl(repairMojibakeString(value));
}

function repairMojibakeDeep(value) {
  if (typeof value === "string") return normalizeTemplateScalarString(value);
  if (Array.isArray(value)) return value.map(repairMojibakeDeep);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.entries(value).map(([key, inner]) => [key, repairMojibakeDeep(inner)])
  );
}

function hasBrokenTemplateText(value) {
  return typeof value === "string" && value.includes("\uFFFD");
}

function repairTemplateVariantBrokenTexts(variant = {}, fallbackVariant = {}) {
  if (!variant || typeof variant !== "object") return variant;
  const repairItems = (items, fallbackItems) => {
    if (!Array.isArray(items)) return items;
    const fallbackById = new Map(
      (Array.isArray(fallbackItems) ? fallbackItems : [])
        .filter((item) => item && typeof item === "object" && item.id && typeof item.text === "string")
        .map((item) => [String(item.id), item.text])
    );
    let changed = false;
    const nextItems = items.map((item, index) => {
      if (!item || typeof item !== "object" || !hasBrokenTemplateText(item.text)) return item;
      const fallbackText = (
        (item.id ? fallbackById.get(String(item.id)) : "")
        || (typeof fallbackItems?.[index]?.text === "string" ? fallbackItems[index].text : "")
      );
      if (!fallbackText || hasBrokenTemplateText(fallbackText)) return item;
      changed = true;
      return { ...item, text: fallbackText };
    });
    return changed ? nextItems : items;
  };
  const nextObjects = repairItems(variant.objects, fallbackVariant.objects);
  const nextTextLayers = repairItems(variant.textLayers, fallbackVariant.textLayers);
  if (nextObjects === variant.objects && nextTextLayers === variant.textLayers) return variant;
  return {
    ...variant,
    objects: nextObjects,
    textLayers: nextTextLayers,
  };
}

function repairBrokenTemplatePreviewText(template = {}) {
  if (!template || typeof template !== "object") return template;
  const fallbackVariant = {
    objects: Array.isArray(template.objects) ? template.objects : [],
    textLayers: Array.isArray(template.textLayers) ? template.textLayers : [],
  };
  const repairedLandscapePreview = template.landscapePreview && typeof template.landscapePreview === "object"
    ? repairTemplateVariantBrokenTexts(template.landscapePreview, fallbackVariant)
    : template.landscapePreview;
  const repairedPortraitPreview = template.portraitPreview && typeof template.portraitPreview === "object"
    ? repairTemplateVariantBrokenTexts(template.portraitPreview, fallbackVariant)
    : template.portraitPreview;
  if (
    repairedLandscapePreview === template.landscapePreview
    && repairedPortraitPreview === template.portraitPreview
  ) {
    return template;
  }
  return {
    ...template,
    landscapePreview: repairedLandscapePreview,
    portraitPreview: repairedPortraitPreview,
  };
}

const TEMPLATE_SOURCE_LABELS = {
  all: "הכל",
  system: "עיצובי מערכת",
  client: "עבודות לקוח",
  personal: "תבניות אישיות",
};
const PERSONAL_TEMPLATE_STORAGE_KEY = "frame_templates";
const CLIENT_TEMPLATE_STORAGE_KEY = "client_templates";
const CLIENT_WORK_ICON = "👤";
const EMPTY_CLIENT_TEMPLATE_META = Object.freeze({
  fullName: "",
  eventDate: "",
  eventMonth: "",
  venueName: "",
  guestCount: "",
  phone: "",
});

const TEMPLATE_STYLE_LABELS = {
  all: "כל הסגנונות",
  wedding: "חתונה",
  bar_mitzvah: "בר מצווה",
  brit: "ברית",
  birthday: "יום הולדת",
  other: "אחר",
};

const TEMPLATE_FRAME_STYLE_LABELS = {
  classic: "קלאסית",
  thin: "דקה",
  strip: "פס יחיד",
  none: "ללא מסגרת",
  other: "אחר",
};

const TEMPLATE_FRAME_STYLE_ORDER = ["classic", "thin", "strip", "none", "other"];

function detectTemplateSource(tpl) {
  if (!tpl || typeof tpl !== "object") return "personal";
  if (tpl.templateSource === "system" || tpl.templateSource === "client" || tpl.templateSource === "personal") {
    return tpl.templateSource;
  }
  if (tpl.isBuiltin) return "system";
  const objects = Array.isArray(tpl.objects) ? tpl.objects : [];
  if (objects.some((obj) => String(obj?.id || "").startsWith("invite-"))) return "client";
  return "personal";
}

function getTemplateDisplayName(tpl) {
  if (!tpl || typeof tpl !== "object") return "";
  return String(
    repairMojibakeString(tpl.heName || tpl.displayName || tpl.name || "")
  ).trim();
}

function normalizeClientEventDate(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (match) return `${match[1]}-${match[2]}-${match[3]}`;
  return raw;
}

function formatInlineLtrText(value) {
  const raw = String(value || "").trim();
  return raw ? `\u2066${raw}\u2069` : "";
}

function formatClientEventDateDisplay(value) {
  const normalized = normalizeClientEventDate(value);
  const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (match) return `${match[3]}-${match[2]}-${match[1]}`;
  return normalized;
}

function normalizeClientGuestCount(value) {
  if (value === null || value === undefined || value === "") return "";
  const digitsOnly = String(value).replace(/[^\d]/g, "");
  if (!digitsOnly) return "";
  const parsed = Number.parseInt(digitsOnly, 10);
  return Number.isFinite(parsed) && parsed >= 0 ? String(parsed) : "";
}

function getEmptyClientTemplateMeta() {
  return { ...EMPTY_CLIENT_TEMPLATE_META };
}

function normalizeClientTemplateMeta(meta = {}) {
  const fullName = repairMojibakeString(meta?.fullName || meta?.clientName || meta?.name || "").trim();
  const eventDate = normalizeClientEventDate(meta?.eventDate || meta?.date || meta?.event_day || "");
  const venueName = repairMojibakeString(meta?.venueName || meta?.hallName || meta?.location || meta?.eventLocation || "").trim();
  const guestCount = normalizeClientGuestCount(meta?.guestCount || meta?.invitedCount || meta?.guests || meta?.guest_amount);
  const phone = repairMojibakeString(meta?.phone || meta?.phoneNumber || meta?.mobile || "").trim();
  return {
    fullName,
    eventDate,
    eventMonth: /^\d{4}-\d{2}-\d{2}$/.test(eventDate) ? eventDate.slice(0, 7) : "",
    venueName,
    guestCount,
    phone,
  };
}

function getClientTemplateMeta(tpl = {}) {
  return normalizeClientTemplateMeta(tpl?.clientMeta || tpl);
}

function buildClientTemplateDisplayName(meta = {}, fallbackName = "") {
  const normalized = normalizeClientTemplateMeta(meta);
  const parts = [
    normalized.fullName,
    normalized.eventDate ? formatInlineLtrText(formatClientEventDateDisplay(normalized.eventDate)) : "",
    normalized.venueName,
  ].filter(Boolean);
  const nextName = parts.join(" · ") || getTemplateDisplayName({ ...meta, name: fallbackName }) || fallbackName || "עבודת לקוח";
  return repairMojibakeString(nextName).trim();
}

function normalizeClientTemplateRecord(template = {}) {
  const clientMeta = getClientTemplateMeta(template);
  const displayName = buildClientTemplateDisplayName(clientMeta, template?.name || template?.originalTemplateName || "");
  return pruneTemplateThumbnail(repairBrokenTemplatePreviewText(repairMojibakeDeep({
    ...template,
    name: displayName,
    heName: displayName,
    displayName,
    templateSource: "client",
    isCustom: true,
    clientMeta,
  })));
}

function buildSavedTemplateSourceState(rawTemplate = {}, rawMode = "landscape", keepText = false, fallbackTextLayers = []) {
  const bgRef = rawTemplate?.bgImageName || rawTemplate?.bgImageSrc || null;
  const bgImageSrc = resolveStyledBgSrcForMode(bgRef, rawMode);
  return normalizeModeStateForDomText({
    objs: sanitizeTemplateObjects(rawTemplate?.objects || rawTemplate?.objs || []),
    textLayers: Array.isArray(rawTemplate?.textLayers) ? rawTemplate.textLayers : [],
    bg: rawTemplate?.bg || "#ffffff",
    bgType: rawTemplate?.bgType || "solid",
    bg2: rawTemplate?.bg2 || "#c8a06e",
    gradAngle: rawTemplate?.gradAngle || 135,
    bgImageSrc,
    safeZone: rawTemplate?.safeZone,
  }, fallbackTextLayers, keepText);
}

function resolveSavedTemplateModeStates(template = {}, options = {}) {
  const keepText = !!options?.keepText;
  const safeTpl = repairBrokenTemplatePreviewText(template);
  const srcMode = safeTpl?.sourceMode === "portrait" ? "portrait" : "landscape";
  const templateBgRef = safeTpl?.bgImageName || safeTpl?.bgImageSrc || null;
  const templateState = buildSavedTemplateSourceState(safeTpl, srcMode, keepText, safeTpl?.textLayers || []);
  const landscapePreviewState = safeTpl?.landscapePreview
    ? buildSavedTemplateSourceState(
        safeTpl.landscapePreview,
        "landscape",
        keepText,
        Array.isArray(safeTpl.landscapePreview?.textLayers) && safeTpl.landscapePreview.textLayers.length
          ? safeTpl.landscapePreview.textLayers
          : (safeTpl.textLayers || [])
      )
    : null;
  const portraitPreviewState = safeTpl?.portraitPreview
    ? buildSavedTemplateSourceState(
        safeTpl.portraitPreview,
        "portrait",
        keepText,
        Array.isArray(safeTpl.portraitPreview?.textLayers) && safeTpl.portraitPreview.textLayers.length
          ? safeTpl.portraitPreview.textLayers
          : (safeTpl.textLayers || [])
      )
    : null;
  const buildModeState = (targetMode) => {
    if (targetMode === "landscape" && srcMode === "portrait" && landscapePreviewState) return landscapePreviewState;
    if (targetMode === "portrait" && srcMode === "landscape" && portraitPreviewState) return portraitPreviewState;
    return normalizeModeStateForDomText({
      ...templateState,
      objs: srcMode === targetMode ? templateState.objs : copyObjsToModeV2(templateState.objs, srcMode, targetMode),
      textLayers: srcMode === targetMode ? templateState.textLayers : copyTextLayersToModeV2(templateState.textLayers, srcMode, targetMode),
      bgImageSrc: resolveStyledBgSrcForMode(templateBgRef || templateState.bgImageSrc, targetMode),
    }, templateState.textLayers, keepText);
  };
  return {
    sourceMode: srcMode,
    landscape: buildModeState("landscape"),
    portrait: buildModeState("portrait"),
    hasLandscapePreview: !!safeTpl?.landscapePreview,
    hasPortraitPreview: !!safeTpl?.portraitPreview,
  };
}

function getSavedTemplateDownloadEntries(template = {}) {
  const resolved = resolveSavedTemplateModeStates(template, { keepText: false });
  const orderedModes = resolved.sourceMode === "portrait"
    ? ["portrait", ...(resolved.hasLandscapePreview ? ["landscape"] : [])]
    : ["landscape", ...(resolved.hasPortraitPreview ? ["portrait"] : [])];
  return orderedModes.map((modeKey) => ({
    modeKey,
    label: modeKey === "portrait" ? "אורך" : "רוחב",
    state: resolved[modeKey],
  }));
}

function getClientTemplateSearchText(tpl = {}) {
  const meta = getClientTemplateMeta(tpl);
  return [
    meta.fullName,
    meta.eventDate,
    meta.eventMonth,
    meta.venueName,
    meta.guestCount,
    meta.phone,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function formatClientTemplateMonthLabel(monthKey = "") {
  const normalized = String(monthKey || "").trim();
  const match = normalized.match(/^(\d{4})-(\d{2})$/);
  if (!match) return "ללא תאריך אירוע";
  const year = match[1];
  const monthIndex = Number.parseInt(match[2], 10);
  const monthLabels = [
    "ינואר",
    "פברואר",
    "מרץ",
    "אפריל",
    "מאי",
    "יוני",
    "יולי",
    "אוגוסט",
    "ספטמבר",
    "אוקטובר",
    "נובמבר",
    "דצמבר",
  ];
  return `${monthLabels[monthIndex - 1] || match[2]} ${year}`.trim();
}

function matchesClientTemplateFilters(tpl, filters = {}) {
  const meta = getClientTemplateMeta(tpl);
  const clientName = String(filters?.clientName || "").trim().toLowerCase();
  const month = String(filters?.month || "").trim();
  const exactDate = normalizeClientEventDate(filters?.exactDate || "");
  const venue = String(filters?.venue || "").trim().toLowerCase();
  const guestCount = normalizeClientGuestCount(filters?.guestCount || "");
  if (clientName && !meta.fullName.toLowerCase().includes(clientName)) return false;
  if (month && meta.eventMonth !== month) return false;
  if (exactDate && meta.eventDate !== exactDate) return false;
  if (venue && !meta.venueName.toLowerCase().includes(venue)) return false;
  if (guestCount && meta.guestCount !== guestCount) return false;
  return true;
}

function getTemplateFrameStyle(tpl) {
  const style = String(tpl?.frameStyle || "").trim();
  return TEMPLATE_FRAME_STYLE_LABELS[style] ? style : "other";
}

function inferTemplateStyle(text) {
  const sample = String(text || "").toLowerCase();
  if (!sample.trim()) return "other";
  if (/בר[\s-]?מצווה|בת[\s-]?מצווה|bar[\s-]?mitzvah|bat[\s-]?mitzvah/.test(sample)) return "bar_mitzvah";
  if (/ברית|בריתה|brit|זבד[\s-]?הבת/.test(sample)) return "brit";
  if (/יום[\s-]?הולדת|birthday|happy birthday/.test(sample)) return "birthday";
  if (/חתונה|מתחתנ|חופה|כלה|חתן|wedding|save the date|love/.test(sample)) return "wedding";
  return "other";
}

function detectTemplateStyle(tpl) {
  if (!tpl || typeof tpl !== "object") return "other";
  const direct = tpl.templateStyle || tpl.eventType || tpl.category;
  if (direct === "bat_mitzvah") return "bar_mitzvah";
  if (direct === "wedding" || direct === "bar_mitzvah" || direct === "brit" || direct === "birthday" || direct === "other") {
    return direct;
  }
  if (tpl.isBuiltin) return "wedding";
  const objectText = (Array.isArray(tpl.objects) ? tpl.objects : [])
    .map((obj) => obj?.text || obj?._emoName || obj?._elementName || "")
    .join(" ");
  return inferTemplateStyle(`${tpl.name || ""} ${objectText}`);
}

function pruneTemplateThumbnail(template = {}) {
  return {
    ...template,
    thumbnail: template.thumbnail && template.thumbnail.length > TEMPLATE_THUMBNAIL_PRUNE_LENGTH ? undefined : template.thumbnail,
  };
}

function normalizeSystemTemplateRecordMap(parsed) {
  if (!parsed || typeof parsed !== "object") return {};
  const entries = Array.isArray(parsed)
    ? parsed.map((tpl) => [tpl?.id, tpl])
    : Object.entries(parsed);
  return Object.fromEntries(
    entries
      .filter(([id, tpl]) => !!id && tpl && typeof tpl === "object")
      .map(([id, tpl]) => [id, pruneTemplateThumbnail(repairBrokenTemplatePreviewText(repairMojibakeDeep({ ...tpl, id })))])
  );
}

function normalizeSystemTemplateStore(parsed) {
  const fallback = { overrides: {}, additions: {}, deletedIds: [] };
  if (!parsed || typeof parsed !== "object") return fallback;
  const candidate = parsed.store && typeof parsed.store === "object" ? parsed.store : parsed;
  const hasStructuredKeys = (
    Object.prototype.hasOwnProperty.call(candidate, "overrides")
    || Object.prototype.hasOwnProperty.call(candidate, "additions")
    || Object.prototype.hasOwnProperty.call(candidate, "deletedIds")
  );
  if (!hasStructuredKeys) {
    return {
      overrides: normalizeSystemTemplateRecordMap(candidate),
      additions: {},
      deletedIds: [],
    };
  }
  return {
    overrides: normalizeSystemTemplateRecordMap(candidate.overrides),
    additions: normalizeSystemTemplateRecordMap(candidate.additions),
    deletedIds: Array.isArray(candidate.deletedIds)
      ? [...new Set(candidate.deletedIds.map((id) => String(id || "").trim()).filter(Boolean))]
      : [],
  };
}

async function loadSystemTemplateStoreFromFile() {
  try {
    const res = await fetch(`${SYSTEM_TEMPLATE_OVERRIDES_FILE_URL}?t=${Date.now()}`, { cache: "no-store" });
    if (!res.ok) return normalizeSystemTemplateStore();
    return normalizeSystemTemplateStore(await res.json());
  } catch (e) {
    return normalizeSystemTemplateStore();
  }
}

function createSystemTemplateId(seed = "system-template") {
  return [
    "sys",
    seed
      .toString()
      .trim()
      .toLowerCase()
      .replace(/[^\w\u0590-\u05FF-]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 24) || "tpl",
    Date.now().toString(36),
    Math.random().toString(36).slice(2, 6),
  ].join("-");
}

function cloneSystemTemplateData(template = {}) {
  try {
    return JSON.parse(JSON.stringify(template));
  } catch (e) {
    return { ...template };
  }
}

function toManagedSystemTemplate(tpl, meta = {}) {
  const {
    systemTemplateKind = "builtin",
    systemTemplateId = tpl?.id || "",
    builtinTemplateId = systemTemplateKind === "builtin" ? (tpl?.builtinTemplateId || tpl?.id || "") : (tpl?.builtinTemplateId || ""),
    sourceTemplateId = tpl?.sourceTemplateId || tpl?.id || "",
    insertAfterId = tpl?.insertAfterId || sourceTemplateId || builtinTemplateId || systemTemplateId || "",
    originalTemplateName = tpl?.originalTemplateName || tpl?.name || "",
  } = meta;
  return pruneTemplateThumbnail({
    ...tpl,
    id: systemTemplateId || tpl?.id || "",
    isBuiltin: true,
    isCustom: false,
    templateSource: "system",
    systemTemplateKind,
    systemTemplateId: systemTemplateId || tpl?.id || "",
    builtinTemplateId,
    sourceTemplateId,
    insertAfterId,
    originalTemplateName,
    templateStyle: tpl?.templateStyle || detectTemplateStyle(tpl),
    originFileName: tpl?.originFileName || "",
  });
}

function getTemplateVariantBgName(template = {}, targetMode = "landscape") {
  const bgRef = template?.bgImageName || template?.bgImageSrc || null;
  if (!bgRef) return null;
  const srcForMode = resolveStyledBgSrcForMode(bgRef, targetMode);
  return resolveStyledBgNameFromSrc(srcForMode) || (typeof bgRef === "string" ? bgRef : null);
}

function projectTemplateVariantToMode(template = {}, targetMode = "landscape") {
  const fallbackSourceMode = template?.sourceMode || "landscape";
  const previewVariant = (
    targetMode === "landscape" && fallbackSourceMode === "portrait" && template?.landscapePreview && typeof template.landscapePreview === "object"
  )
    ? { ...template.landscapePreview, sourceMode: "landscape" }
    : (
      targetMode === "portrait" && fallbackSourceMode === "landscape" && template?.portraitPreview && typeof template.portraitPreview === "object"
    )
      ? { ...template.portraitPreview, sourceMode: "portrait" }
      : template;
  const sourceMode = previewVariant?.sourceMode || fallbackSourceMode;
  const baseObjects = sanitizeTemplateObjects(previewVariant?.objects || []);
  const baseTextLayers = Array.isArray(previewVariant?.textLayers)
    ? previewVariant.textLayers.map(cloneTextLayer)
    : [];
  return {
    sourceMode: targetMode,
    frameStyle: previewVariant?.frameStyle || template?.frameStyle || "classic",
    safeZone: normalizeSafeZone(previewVariant?.safeZone || template?.safeZone),
    bg: previewVariant?.bg || template?.bg || "#ffffff",
    bgType: previewVariant?.bgType || template?.bgType || "solid",
    bg2: previewVariant?.bg2 || template?.bg2 || "#c8a06e",
    gradAngle: previewVariant?.gradAngle || template?.gradAngle || 135,
    bgImageName: getTemplateVariantBgName(previewVariant, targetMode) || getTemplateVariantBgName(template, targetMode),
    objects: sourceMode === targetMode ? baseObjects : copyObjsToModeV2(baseObjects, sourceMode, targetMode),
    textLayers: sourceMode === targetMode ? baseTextLayers : copyTextLayersToModeV2(baseTextLayers, sourceMode, targetMode),
  };
}

function mergeTemplateObjectArrays(baseObjects = [], overrideObjects = []) {
  const merged = baseObjects.map((item) => cloneSystemTemplateData(item));
  const keyToIndex = new Map();
  merged.forEach((item, index) => {
    const key = item?.id ? `id:${item.id}` : `idx:${index}:${item?.type || "item"}`;
    keyToIndex.set(key, index);
  });
  overrideObjects.forEach((item, index) => {
    if (!item || typeof item !== "object") return;
    const key = item?.id ? `id:${item.id}` : `override:${index}:${item?.type || "item"}`;
    const cloned = cloneSystemTemplateData(item);
    if (keyToIndex.has(key)) {
      merged[keyToIndex.get(key)] = cloned;
      return;
    }
    keyToIndex.set(key, merged.length);
    merged.push(cloned);
  });
  return merged.filter(Boolean);
}

function mergeTemplateVariantData(baseVariant = {}, overrideVariant = {}, targetMode = "landscape") {
  const baseAllObjects = [
    ...sanitizeTemplateObjects(baseVariant?.objects || []),
    ...(Array.isArray(baseVariant?.textLayers)
      ? baseVariant.textLayers.map(domTextLayerToSerializedObject).filter(Boolean)
      : []),
  ];
  const overrideAllObjects = [
    ...sanitizeTemplateObjects(overrideVariant?.objects || []),
    ...(Array.isArray(overrideVariant?.textLayers)
      ? overrideVariant.textLayers.map(domTextLayerToSerializedObject).filter(Boolean)
      : []),
  ];
  return {
    sourceMode: targetMode,
    frameStyle: overrideVariant?.frameStyle || baseVariant?.frameStyle || "classic",
    safeZone: normalizeSafeZone(overrideVariant?.safeZone || baseVariant?.safeZone),
    bg: overrideVariant?.bg || baseVariant?.bg || "#ffffff",
    bgType: overrideVariant?.bgType || baseVariant?.bgType || "solid",
    bg2: overrideVariant?.bg2 || baseVariant?.bg2 || "#c8a06e",
    gradAngle: overrideVariant?.gradAngle || baseVariant?.gradAngle || 135,
    bgImageName: overrideVariant?.bgImageName || baseVariant?.bgImageName || null,
    objects: mergeTemplateObjectArrays(baseAllObjects, overrideAllObjects),
    textLayers: [],
  };
}

function mergeBuiltinTemplateWithOverride(baseTemplate, overrideTemplate) {
  if (!overrideTemplate || typeof overrideTemplate !== "object") {
    return baseTemplate;
  }
  if (overrideTemplate?.overrideMergeMode === "replace") {
    return {
      ...baseTemplate,
      ...overrideTemplate,
      objects: sanitizeTemplateObjects(overrideTemplate?.objects || []),
      textLayers: Array.isArray(overrideTemplate?.textLayers)
        ? overrideTemplate.textLayers.map(cloneTextLayer)
        : [],
      landscapePreview: overrideTemplate?.landscapePreview && typeof overrideTemplate.landscapePreview === "object"
        ? {
            ...overrideTemplate.landscapePreview,
            objects: sanitizeTemplateObjects(overrideTemplate.landscapePreview.objects || []),
            textLayers: Array.isArray(overrideTemplate.landscapePreview.textLayers)
              ? overrideTemplate.landscapePreview.textLayers.map(cloneTextLayer)
              : [],
          }
        : (overrideTemplate?.landscapePreview || null),
      portraitPreview: overrideTemplate?.portraitPreview && typeof overrideTemplate.portraitPreview === "object"
        ? {
            ...overrideTemplate.portraitPreview,
            objects: sanitizeTemplateObjects(overrideTemplate.portraitPreview.objects || []),
            textLayers: Array.isArray(overrideTemplate.portraitPreview.textLayers)
              ? overrideTemplate.portraitPreview.textLayers.map(cloneTextLayer)
              : [],
          }
        : (overrideTemplate?.portraitPreview || null),
    };
  }
  const mainMode = overrideTemplate?.sourceMode || baseTemplate?.sourceMode || "landscape";
  const mergedMainVariant = mergeTemplateVariantData(
    projectTemplateVariantToMode(baseTemplate, mainMode),
    projectTemplateVariantToMode({ ...overrideTemplate, sourceMode: mainMode }, mainMode),
    mainMode,
  );
  const mergedLandscapePreview = (() => {
    const baseLandscape = projectTemplateVariantToMode(baseTemplate, "landscape");
    if (overrideTemplate?.landscapePreview && typeof overrideTemplate.landscapePreview === "object") {
      return mergeTemplateVariantData(
        baseLandscape,
        projectTemplateVariantToMode({
          ...overrideTemplate.landscapePreview,
          sourceMode: "landscape",
          frameStyle: overrideTemplate?.frameStyle || baseTemplate?.frameStyle || "classic",
        }, "landscape"),
        "landscape",
      );
    }
    if (mainMode === "portrait") {
      return mergeTemplateVariantData(
        baseLandscape,
        projectTemplateVariantToMode({ ...mergedMainVariant, sourceMode: mainMode }, "landscape"),
        "landscape",
      );
    }
    return null;
  })();
  const mergedPortraitPreview = (() => {
    const basePortrait = projectTemplateVariantToMode(baseTemplate, "portrait");
    if (overrideTemplate?.portraitPreview && typeof overrideTemplate.portraitPreview === "object") {
      return mergeTemplateVariantData(
        basePortrait,
        projectTemplateVariantToMode({
          ...overrideTemplate.portraitPreview,
          sourceMode: "portrait",
          frameStyle: overrideTemplate?.frameStyle || baseTemplate?.frameStyle || "classic",
        }, "portrait"),
        "portrait",
      );
    }
    if (mainMode === "landscape") {
      return mergeTemplateVariantData(
        basePortrait,
        projectTemplateVariantToMode({ ...mergedMainVariant, sourceMode: mainMode }, "portrait"),
        "portrait",
      );
    }
    return null;
  })();
  return {
    ...baseTemplate,
    ...overrideTemplate,
    sourceMode: mainMode,
    frameStyle: mergedMainVariant.frameStyle,
    safeZone: mergedMainVariant.safeZone,
    bg: mergedMainVariant.bg,
    bgType: mergedMainVariant.bgType,
    bg2: mergedMainVariant.bg2,
    gradAngle: mergedMainVariant.gradAngle,
    bgImageName: mergedMainVariant.bgImageName,
    objects: mergedMainVariant.objects,
    textLayers: mergedMainVariant.textLayers,
    landscapePreview: mergedLandscapePreview,
    portraitPreview: mergedPortraitPreview,
  };
}

function mergeBuiltInTemplatesWithSystemStore(store) {
  const normalizedStore = normalizeSystemTemplateStore(store);
  const deletedIds = new Set(normalizedStore.deletedIds);
  const additionsByAfterId = new Map();
  const additionTemplates = Object.values(normalizedStore.additions || {}).map((tpl) => toManagedSystemTemplate(tpl, {
    systemTemplateKind: "addition",
    systemTemplateId: tpl?.systemTemplateId || tpl?.id || "",
    builtinTemplateId: tpl?.builtinTemplateId || "",
    sourceTemplateId: tpl?.sourceTemplateId || tpl?.id || "",
    insertAfterId: tpl?.insertAfterId || tpl?.sourceTemplateId || tpl?.builtinTemplateId || tpl?.id || "",
    originalTemplateName: tpl?.originalTemplateName || tpl?.name || "",
  }));
  additionTemplates.forEach((tpl) => {
    const key = tpl.insertAfterId || "__tail__";
    if (!additionsByAfterId.has(key)) additionsByAfterId.set(key, []);
    additionsByAfterId.get(key).push(tpl);
  });

  const appendChildren = (parentId, output, seen = new Set()) => {
    const key = parentId || "__tail__";
    const children = additionsByAfterId.get(key) || [];
    children.forEach((child) => {
      if (!child?.id || seen.has(child.id) || deletedIds.has(child.id)) return;
      seen.add(child.id);
      output.push(child);
      appendChildren(child.id, output, seen);
    });
    return seen;
  };

  const merged = [];
  const seenAdditionIds = new Set();
  BUILTIN.forEach((tpl) => {
    if (deletedIds.has(tpl.id)) return;
    const override = normalizedStore.overrides[tpl.id];
    const mergedTpl = toManagedSystemTemplate({
      ...mergeBuiltinTemplateWithOverride(tpl, override),
      id: tpl.id,
      name: override?.name || tpl.name,
    }, {
      systemTemplateKind: "builtin",
      systemTemplateId: tpl.id,
      builtinTemplateId: tpl.id,
      sourceTemplateId: tpl.id,
      insertAfterId: tpl.id,
      originalTemplateName: tpl.name || "",
    });
    merged.push(mergedTpl);
    appendChildren(tpl.id, merged, seenAdditionIds);
  });

  additionTemplates.forEach((tpl) => {
    if (!tpl?.id || seenAdditionIds.has(tpl.id) || deletedIds.has(tpl.id)) return;
    seenAdditionIds.add(tpl.id);
    merged.push(tpl);
    appendChildren(tpl.id, merged, seenAdditionIds);
  });

  return merged;
}

function getTemplateSearchText(tpl) {
  return [
    getTemplateDisplayName(tpl),
    tpl?.name,
    tpl?.heName,
    tpl?.legacyName,
    tpl?.originalTemplateName,
    TEMPLATE_FRAME_STYLE_LABELS[getTemplateFrameStyle(tpl)],
    TEMPLATE_SOURCE_LABELS[detectTemplateSource(tpl)],
    TEMPLATE_STYLE_LABELS[detectTemplateStyle(tpl)],
    tpl?.templateSource === "client" ? "הזמנה לקוח לקוחות" : "",
    tpl?.isBuiltin ? "מערכת מובנה מוכן" : "",
    tpl?.isCustom ? "אישי שמור" : "",
    getClientTemplateSearchText(tpl),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function loadStoredTemplateList(storageKey) {
  if (typeof window === "undefined") return [];
  try {
    const parsed = JSON.parse(localStorage.getItem(storageKey) || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    return [];
  }
}

function dedupeTemplateRecords(items = []) {
  const byId = new Map();
  items.forEach((item, index) => {
    if (!item || typeof item !== "object") return;
    const key = String(item.id || `idx:${index}`);
    byId.set(key, item);
  });
  return [...byId.values()];
}

function loadPersonalTemplatesFromStorage() {
  return loadStoredTemplateList(PERSONAL_TEMPLATE_STORAGE_KEY)
    .map((tpl) => pruneTemplateThumbnail(repairMojibakeDeep(tpl)))
    .filter((tpl) => detectTemplateSource(tpl) !== "client");
}

function loadClientTemplatesFromStorage() {
  const dedicated = loadStoredTemplateList(CLIENT_TEMPLATE_STORAGE_KEY).map(normalizeClientTemplateRecord);
  const legacy = loadStoredTemplateList(PERSONAL_TEMPLATE_STORAGE_KEY)
    .map((tpl) => pruneTemplateThumbnail(repairMojibakeDeep(tpl)))
    .filter((tpl) => detectTemplateSource(tpl) === "client")
    .map(normalizeClientTemplateRecord);
  // Prefer records from the dedicated client storage over legacy client items
  // that may still exist inside the personal template bucket from older builds.
  return dedupeTemplateRecords([...legacy, ...dedicated]);
}

function sanitizeTemplateObjects(objs) {
  if (!Array.isArray(objs)) return [];
  return objs
    .filter(o => o && typeof o === "object")
    .filter(o => !(o.type === "image" && typeof o.src === "string" && o.src.includes("__TRUNCATED__")))
    .map(normalizeSerializedObject)
    .filter(Boolean);
}

function isSerializedTextObject(obj) {
  if (!obj) return false;
  const isTextual = obj.type === "i-text" || obj.type === "text" || obj.type === "textbox";
  if (!isTextual) return false;
  // Mobile DOM text layers should contain only editable text content.
  // Decorative text-based elements (emoji/hearts/stars/invite decorations) must stay on-canvas
  // so copy-to-mode and element interactions treat them like elements instead of text.
  if (
    obj._emoName
    || obj._elementName
    || String(obj?.id || "").startsWith("invite-decoration")
    || looksLikeCenterDecorId(obj?.id)
  ) {
    return false;
  }
  return true;
}

function isEditableCanvasTextObject(obj) {
  return isSerializedTextObject(obj);
}

function cloneTextLayer(layer = {}) {
  const nextText = repairMojibakeString(String(layer.text ?? ""));
  return {
    id: layer.id || Date.now().toString(),
    text: nextText,
    fontFamily: layer.fontFamily || "Heebo",
    fontSize: typeof layer.fontSize === "number" ? layer.fontSize : 60,
    fill: layer.fill || "#222222",
    fontWeight: layer.fontWeight || "normal",
    shadow: normalizeTextShadowValue(layer.shadow),
    halo: !!layer.halo,
    stroke: layer.stroke || "#000000",
    strokeWidth: typeof layer.strokeWidth === "number" ? layer.strokeWidth : 0,
    x: typeof layer.x === "number" ? layer.x : (typeof layer.left === "number" ? layer.left : DIMS.landscape.w / 2),
    y: typeof layer.y === "number" ? layer.y : (typeof layer.top === "number" ? layer.top : (DIMS.landscape.h - PAD.landscape.b / 2)),
    rotation: typeof layer.rotation === "number" ? layer.rotation : (typeof layer.angle === "number" ? layer.angle : 0),
    opacity: typeof layer.opacity === "number" ? layer.opacity : 1,
    textAlign: layer.textAlign || "center",
    direction: inferTextDirection(nextText, layer.direction),
    lineHeight: typeof layer.lineHeight === "number" ? layer.lineHeight : 1.2,
    scaleX: typeof layer.scaleX === "number" ? layer.scaleX : 1,
    scaleY: typeof layer.scaleY === "number" ? layer.scaleY : 1,
  };
}

function domTextLayerToSerializedObject(layer = {}) {
  const next = cloneTextLayer(layer);
  return normalizeSerializedObject({
    type: "i-text",
    id: next.id,
    text: next.text,
    left: next.x,
    top: next.y,
    angle: next.rotation,
    fontFamily: next.fontFamily,
    fontSize: next.fontSize,
    fill: next.fill,
    fontWeight: next.fontWeight,
    originX: "center",
    originY: "center",
    textAlign: next.textAlign,
    direction: next.direction,
    lineHeight: next.lineHeight,
    scaleX: next.scaleX,
    scaleY: next.scaleY,
    opacity: next.opacity,
    stroke: next.strokeWidth > 0 ? next.stroke : undefined,
    strokeWidth: next.strokeWidth > 0 ? next.strokeWidth : 0,
    paintFirst: "stroke",
    halo: !!next.halo,
    shadow: normalizeTextShadowValue(next.shadow),
    selectable: true,
    evented: true,
  });
}

function serializedTextObjectToDomLayer(obj, index = 0) {
  return cloneTextLayer({
    id: obj.id || `dom-text-${Date.now()}-${index}`,
    text: obj.text || "",
    fontFamily: obj.fontFamily,
    fontSize: obj.fontSize,
    fill: obj.fill,
    fontWeight: obj.fontWeight,
    shadow: obj.shadow,
    halo: obj.halo,
    stroke: obj.stroke,
    strokeWidth: obj.strokeWidth,
    x: obj.left,
    y: obj.top,
    rotation: obj.angle,
    opacity: obj.opacity,
    textAlign: obj.textAlign || "center",
    direction: obj.direction,
    lineHeight: obj.lineHeight,
    scaleX: obj.scaleX,
    scaleY: obj.scaleY,
  });
}

function splitSerializedTextLayersFromObjects(objs = []) {
  const textLayers = [];
  const shapeObjects = [];
  objs.forEach((obj, index) => {
    if (!obj || typeof obj !== "object") return;
    if (isSerializedTextObject(obj)) {
      textLayers.push(serializedTextObjectToDomLayer(obj, index));
      return;
    }
    shapeObjects.push(obj);
  });
  return { textLayers, objects: shapeObjects };
}

function safeEnlivenObjects(objs, onReady) {
  const normalized = normalizeSerializedObjects(objs).map(sanitizeFabricTextObjectForCanvas);
  try {
    window.fabric.util.enlivenObjects(normalized, revived => {
      (revived || []).forEach(obj => {
        if (isFabricTextGeometryObject(obj)) {
          if (obj.styles == null || typeof obj.styles !== "object") obj.styles = {};
          const uiFontFamily = obj._uiFontFamily || extractUiFontFamily(obj.fontFamily);
          obj._uiFontFamily = uiFontFamily;
          obj.editable = obj.editable !== false;
          obj.set({ fontFamily: resolveFabricFontFamily(uiFontFamily, obj.text || "") });
        }
        refreshFabricTextGeometry(obj);
      });
      onReady(revived || []);
    });
  } catch (err) {
    console.error("safeEnlivenObjects failed, retrying object-by-object", err, normalized);
    if (!normalized.length) {
      onReady([]);
      return;
    }
    const revived = [];
    let pending = normalized.length;
    const finish = () => {
      pending -= 1;
      if (pending <= 0) onReady(revived);
    };
    normalized.forEach(obj => {
      try {
        window.fabric.util.enlivenObjects([obj], items => {
          if (items?.[0]) {
            if (isFabricTextGeometryObject(items[0])) {
              if (items[0].styles == null || typeof items[0].styles !== "object") items[0].styles = {};
              const uiFontFamily = items[0]._uiFontFamily || extractUiFontFamily(items[0].fontFamily);
              items[0]._uiFontFamily = uiFontFamily;
              items[0].editable = items[0].editable !== false;
              items[0].set({ fontFamily: resolveFabricFontFamily(uiFontFamily, items[0].text || "") });
            }
            refreshFabricTextGeometry(items[0]);
            revived.push(items[0]);
          }
          finish();
        });
      } catch (singleErr) {
        console.warn("Skipping broken object during restore", singleErr, obj);
        finish();
      }
    });
  }
}

function isFabricCanvasUsable(canvas) {
  return !!(canvas && canvas.lowerCanvasEl && canvas.contextContainer);
}

function safeRenderCanvas(canvas) {
  if (!isFabricCanvasUsable(canvas)) return false;
  try {
    canvas.renderAll();
    return true;
  } catch (err) {
    console.warn("safeRenderCanvas skipped disposed canvas", err);
    return false;
  }
}

function isFabricTextGeometryObject(obj) {
  return !!obj && (obj.type === "i-text" || obj.type === "text" || obj.type === "textbox");
}

function refreshFabricTextGeometry(obj, canvas = null) {
  if (!isFabricTextGeometryObject(obj)) return;
  try {
    obj.objectCaching = false;
    obj.noScaleCache = true;
    obj.dirty = true;
    if (typeof obj._clearCache === "function") obj._clearCache();
    if (typeof obj.initDimensions === "function") obj.initDimensions();
    if (typeof obj.setCoords === "function") obj.setCoords();
    if (canvas?.calcOffset) canvas.calcOffset();
  } catch (err) {
    console.warn("refreshFabricTextGeometry failed", err, obj);
  }
}

function refreshCanvasTextGeometry(canvas) {
  if (!canvas?.getObjects) return;
  canvas.getObjects().forEach(obj => refreshFabricTextGeometry(obj, canvas));
  canvas.requestRenderAll?.();
}

function serializeObjs(canvas) {
  try {
    if (!canvas || !canvas.getObjects) {
      console.warn("serializeObjs: canvas not ready");
      return [];
    }
    const allObjs = canvas.getObjects();
    if (!allObjs || allObjs.length === 0) {
      console.warn("serializeObjs: no objects found");
      return [];
    }
    
    const serialized = [];
    allObjs.forEach(o => {
      if (!isUser(o)) return; // Skip system objects
      try {
        // FIX: Use safe serialization - don't pass properties that might cause errors
        const json = normalizeSerializedObject(o.toJSON());
        // Ensure we keep the important metadata
        if (!json) return;
        if (o.id) json.id = o.id;
        if (o._emoName) json._emoName = o._emoName;
        if (o._elementName) json._elementName = o._elementName;
        if (o._isShapeElement) json._isShapeElement = true;
        if (o._shapeKind) json._shapeKind = o._shapeKind;
        if (o._shapeStrokeOnly) json._shapeStrokeOnly = true;
        if (typeof o._shapeCornerRadius === "number") json._shapeCornerRadius = o._shapeCornerRadius;
        json.halo = !!o.halo;
        if (o.type === "i-text" || o.type === "text" || o.type === "textbox") {
          json._uiFontFamily = o._uiFontFamily || extractUiFontFamily(o.fontFamily);
          json.fontFamily = json._uiFontFamily;
          json.fill = o.fill;
          json.stroke = o.stroke || null;
          json.strokeWidth = typeof o.strokeWidth === "number" ? o.strokeWidth : 0;
          json.shadow = normalizeTextShadowValue(o.shadow);
          json.paintFirst = o.paintFirst || "stroke";
          json.fontWeight = o.fontWeight || "normal";
          json.textAlign = o.textAlign || "center";
          json.direction = inferTextDirection(o.text || "", o.direction);
          json.lineHeight = typeof o.lineHeight === "number" ? o.lineHeight : 1.2;
          json.scaleX = typeof o.scaleX === "number" ? o.scaleX : 1;
          json.scaleY = typeof o.scaleY === "number" ? o.scaleY : 1;
          delete json.width;
          delete json.height;
        }
        json.selectable = true;
        json.evented = true;
        serialized.push(json);
      } catch(itemErr) {
        console.warn("Failed to serialize single object:", itemErr, o);
        // Try a minimal backup serialization
        try {
          const backup = normalizeSerializedObject({
            type: o.type,
            left: o.left,
            top: o.top,
            scaleX: o.scaleX,
            scaleY: o.scaleY,
            angle: o.angle,
            opacity: o.opacity,
            id: o.id,
            _emoName: o._emoName,
            halo: !!o.halo,
          });
          if (o.type === "i-text" || o.type === "text" || o.type === "textbox") {
            backup.text = o.text;
            backup.fontSize = o.fontSize;
            backup._uiFontFamily = o._uiFontFamily || extractUiFontFamily(o.fontFamily);
            backup.fontFamily = backup._uiFontFamily;
            backup.fill = o.fill;
            backup.stroke = o.stroke || null;
            backup.strokeWidth = typeof o.strokeWidth === "number" ? o.strokeWidth : 0;
            backup.shadow = normalizeTextShadowValue(o.shadow);
            backup.paintFirst = o.paintFirst || "stroke";
            backup.fontWeight = o.fontWeight;
            backup.originX = o.originX;
            backup.originY = o.originY;
            backup.textAlign = o.textAlign || "center";
            backup.direction = inferTextDirection(o.text || "", o.direction);
            backup.lineHeight = typeof o.lineHeight === "number" ? o.lineHeight : 1.2;
          }
          serialized.push(backup);
        } catch(backupErr) {
          console.error("Even backup serialization failed:", backupErr);
        }
      }
    });
    
    if (serialized.length === 0) {
      console.warn("serializeObjs: no objects were successfully serialized");
    }
    return serialized;
  } catch(e) { 
    console.error("serializeObjs critical error:", e);
    return []; 
  }
}

// ── Compute canvas background value (solid string or Fabric.Gradient) ──
function computeBgValue(type, c1, c2, angle, w, h) {
  if (!isGradientBgType(type) || !window.fabric) return c1;
  if (type === "radial") {
    return new window.fabric.Gradient({
      type: "radial",
      gradientUnits: "pixels",
      coords: {
        x1: w / 2,
        y1: h / 2,
        r1: 0,
        x2: w / 2,
        y2: h / 2,
        r2: Math.max(w, h) * 0.68,
      },
      colorStops: [{ offset: 0, color: c1 }, { offset: 1, color: c2 }],
    });
  }
  const rad = (angle * Math.PI) / 180;
  const cx = w / 2, cy = h / 2;
  const d  = Math.sqrt(w * w + h * h);
  return new window.fabric.Gradient({
    type: 'linear',
    gradientUnits: 'pixels',
    coords: {
      x1: cx - Math.cos(rad) * d / 2,
      y1: cy - Math.sin(rad) * d / 2,
      x2: cx + Math.cos(rad) * d / 2,
      y2: cy + Math.sin(rad) * d / 2,
    },
    colorStops: [{ offset: 0, color: c1 }, { offset: 1, color: c2 }],
  });
}

// ── Styled BG: cover-scale + feathered edges → dataURL ──
function buildBgDataURL(imgSrc, canvasW, canvasH, bgColor, callback) {
  const img = new Image();
  img.onload = () => {
    // ── 1. Cover scaling ──
    const scaleX = canvasW / img.naturalWidth;
    const scaleY = canvasH / img.naturalHeight;
    const scale  = Math.max(scaleX, scaleY);
    const scaledW = img.naturalWidth  * scale;
    const scaledH = img.naturalHeight * scale;
    const offsetX = (canvasW - scaledW) / 2;
    const offsetY = (canvasH - scaledH) / 2;

    // ── 2. Parse bgColor for feather gradients ──
    const hex = (bgColor || "#ffffff").replace("#","");
    const rD = parseInt(hex.slice(0,2),16)||255;
    const gD = parseInt(hex.slice(2,4),16)||255;
    const bD = parseInt(hex.slice(4,6),16)||255;

    // ── 3. Fill base with bgColor → draw image over it ──
    const baseC = document.createElement("canvas");
    baseC.width = canvasW; baseC.height = canvasH;
    const baseCtx = baseC.getContext("2d");
    baseCtx.fillStyle = bgColor || "#ffffff";
    baseCtx.fillRect(0, 0, canvasW, canvasH);
    baseCtx.drawImage(img, offsetX, offsetY, scaledW, scaledH);

    // ── 4. bgColor gradient overlay at overflow edges ──
    const featherX = Math.round(canvasW * 0.09);
    const featherY = Math.round(canvasH * 0.07);
    const stops = [[0,0.92],[0.28,0.55],[0.58,0.18],[0.80,0.04],[0.93,0.01],[1,0]];
    const mkLin = (x1,y1,x2,y2) => {
      const g = baseCtx.createLinearGradient(x1,y1,x2,y2);
      stops.forEach(([t,a]) => g.addColorStop(t,`rgba(${rD},${gD},${bD},${a})`));
      return g;
    };
    const mkRad = (cx,cy,r) => {
      const g = baseCtx.createRadialGradient(cx,cy,0,cx,cy,r);
      stops.forEach(([t,a]) => g.addColorStop(t,`rgba(${rD},${gD},${bD},${a})`));
      return g;
    };
    const overX = offsetX < -1;
    const overY = offsetY < -1;
    const fX = featherX, fY = featherY;
    if (overX && overY) {
      const cR = Math.sqrt(fX*fX + fY*fY);
      baseCtx.fillStyle = mkLin(0,0,fX,0);               baseCtx.fillRect(0,          fY, fX, canvasH-fY*2);
      baseCtx.fillStyle = mkLin(canvasW,0,canvasW-fX,0); baseCtx.fillRect(canvasW-fX, fY, fX, canvasH-fY*2);
      baseCtx.fillStyle = mkLin(0,0,0,fY);               baseCtx.fillRect(fX, 0,          canvasW-fX*2, fY);
      baseCtx.fillStyle = mkLin(0,canvasH,0,canvasH-fY); baseCtx.fillRect(fX, canvasH-fY, canvasW-fX*2, fY);
      baseCtx.fillStyle = mkRad(0,0,cR);                 baseCtx.fillRect(0,          0,          fX, fY);
      baseCtx.fillStyle = mkRad(canvasW,0,cR);           baseCtx.fillRect(canvasW-fX, 0,          fX, fY);
      baseCtx.fillStyle = mkRad(0,canvasH,cR);           baseCtx.fillRect(0,          canvasH-fY, fX, fY);
      baseCtx.fillStyle = mkRad(canvasW,canvasH,cR);     baseCtx.fillRect(canvasW-fX, canvasH-fY, fX, fY);
    } else if (overX) {
      const cR = fX * 1.3;
      baseCtx.fillStyle = mkLin(0,0,fX,0);               baseCtx.fillRect(0,          fX, fX, canvasH-fX*2);
      baseCtx.fillStyle = mkLin(canvasW,0,canvasW-fX,0); baseCtx.fillRect(canvasW-fX, fX, fX, canvasH-fX*2);
      baseCtx.fillStyle = mkRad(0,0,cR);                 baseCtx.fillRect(0,          0,          fX, fX);
      baseCtx.fillStyle = mkRad(canvasW,0,cR);           baseCtx.fillRect(canvasW-fX, 0,          fX, fX);
      baseCtx.fillStyle = mkRad(0,canvasH,cR);           baseCtx.fillRect(0,          canvasH-fX, fX, fX);
      baseCtx.fillStyle = mkRad(canvasW,canvasH,cR);     baseCtx.fillRect(canvasW-fX, canvasH-fX, fX, fX);
    } else if (overY) {
      const cR = fY * 1.3;
      baseCtx.fillStyle = mkLin(0,0,0,fY);               baseCtx.fillRect(fY, 0,          canvasW-fY*2, fY);
      baseCtx.fillStyle = mkLin(0,canvasH,0,canvasH-fY); baseCtx.fillRect(fY, canvasH-fY, canvasW-fY*2, fY);
      baseCtx.fillStyle = mkRad(0,0,cR);                 baseCtx.fillRect(0,          0,          fY, fY);
      baseCtx.fillStyle = mkRad(canvasW,0,cR);           baseCtx.fillRect(canvasW-fY, 0,          fY, fY);
      baseCtx.fillStyle = mkRad(0,canvasH,cR);           baseCtx.fillRect(0,          canvasH-fY, fY, fY);
      baseCtx.fillStyle = mkRad(canvasW,canvasH,cR);     baseCtx.fillRect(canvasW-fY, canvasH-fY, fY, fY);
    }

    callback(baseC.toDataURL("image/jpeg", 0.93));
  };
  img.onerror = () => callback(null);
  img.src = imgSrc;
}

// FIX #8: clamp uses absolute bounding rect
function overflowAllowanceForObject(obj) {
  const id = String(obj?.id || "");
  const isInviteDecoration = id.startsWith("invite-decoration");
  const isDecorationImage = obj?.type === "image" && (
    isInviteDecoration
    || Boolean(obj?._elementName)
    || Boolean(obj?._emoName)
  );
  if (!isDecorationImage) return { x: 0, y: 0 };
  const width = Math.max(0, obj?.getScaledWidth?.() || obj?.width || 0);
  const height = Math.max(0, obj?.getScaledHeight?.() || obj?.height || 0);
  const baseX = isInviteDecoration ? 0.34 : 0.2;
  const baseY = isInviteDecoration ? 0.28 : 0.18;
  return {
    x: Math.min(180, Math.max(22, width * baseX)),
    y: Math.min(160, Math.max(18, height * baseY)),
  };
}

function clamp(obj, dims) {
  if (!obj) return;
  try {
    obj.setCoords();
    const b = obj.getBoundingRect(true, true);
    const overflow = overflowAllowanceForObject(obj);
    let x = obj.left, y = obj.top;
    if (b.left < -overflow.x) x -= (b.left + overflow.x);
    if (b.top  < -overflow.y) y -= (b.top + overflow.y);
    if (b.left + b.width  > dims.w + overflow.x) x -= (b.left + b.width - dims.w - overflow.x);
    if (b.top  + b.height > dims.h + overflow.y) y -= (b.top + b.height - dims.h - overflow.y);
    obj.set({ left: x, top: y });
    obj.setCoords();
  } catch(e) {}
}

function getDefaultSafeZone() {
  return {
    top: { on: false, mm: SAFE_ZONE_DEFAULT_MM },
    bottom: { on: false, mm: SAFE_ZONE_DEFAULT_MM },
    left: { on: false, mm: SAFE_ZONE_DEFAULT_MM },
    right: { on: false, mm: SAFE_ZONE_DEFAULT_MM },
    visible: true,
  };
}

function normalizeSafeZone(value) {
  const base = getDefaultSafeZone();
  const next = value && typeof value === "object" ? value : {};
  const normalized = { ...base };
  SAFE_ZONE_EDGES.forEach((edge) => {
    const incoming = next?.[edge] && typeof next[edge] === "object" ? next[edge] : {};
    const mm = Number(incoming.mm);
    normalized[edge] = {
      on: !!incoming.on,
      mm: Number.isFinite(mm) ? Math.max(SAFE_ZONE_MIN_MM, Math.min(SAFE_ZONE_MAX_MM, mm)) : base[edge].mm,
    };
  });
  normalized.visible = next?.visible !== false;
  return normalized;
}

function getSafeZoneCanvasBounds(mode, safeZone) {
  const dims = DIMS[mode] || DIMS.landscape;
  const sizeCm = FRAME_SIZE_CM[mode] || FRAME_SIZE_CM.landscape;
  const normalized = normalizeSafeZone(safeZone);
  const pxPerMmX = dims.w / Math.max(1, sizeCm.w * 10);
  const pxPerMmY = dims.h / Math.max(1, sizeCm.h * 10);
  return {
    top: normalized.top.on ? normalized.top.mm * pxPerMmY : 0,
    bottom: normalized.bottom.on ? dims.h - (normalized.bottom.mm * pxPerMmY) : dims.h,
    left: normalized.left.on ? normalized.left.mm * pxPerMmX : 0,
    right: normalized.right.on ? dims.w - (normalized.right.mm * pxPerMmX) : dims.w,
    visible: normalized.visible,
    activeEdges: SAFE_ZONE_EDGES.filter((edge) => normalized[edge].on),
  };
}

function isTextObject(obj) {
  if (!obj) return false;
  if (obj._isMobileText) return true;
  return isSerializedTextObject(obj) || obj.type === "i-text" || obj.type === "text" || obj.type === "textbox";
}

function isNonTextUserObject(obj) {
  if (!obj) return false;
  if (obj._isMobileText) return false;
  if (typeof obj.getBoundingRect === "function") return isUser(obj) && !isTextObject(obj);
  return !isSerializedTextObject(obj);
}

function doesRectCrossSafeZone(rect, bounds, activeEdges = bounds?.activeEdges || []) {
  if (!rect || !bounds || !activeEdges.length) return false;
  if (activeEdges.includes("top") && rect.top < bounds.top) return true;
  if (activeEdges.includes("bottom") && rect.bottom > bounds.bottom) return true;
  if (activeEdges.includes("left") && rect.left < bounds.left) return true;
  if (activeEdges.includes("right") && rect.right > bounds.right) return true;
  return false;
}

function clampRectToSafeZone(rect, bounds, activeEdges = bounds?.activeEdges || []) {
  const next = normalizeSnapRect(rect);
  if (!bounds || !activeEdges.length) return next;
  if (activeEdges.includes("left") && next.left < bounds.left) {
    const delta = bounds.left - next.left;
    next.left += delta; next.right += delta; next.centerX += delta;
  }
  if (activeEdges.includes("right") && next.right > bounds.right) {
    const delta = next.right - bounds.right;
    next.left -= delta; next.right -= delta; next.centerX -= delta;
  }
  if (activeEdges.includes("top") && next.top < bounds.top) {
    const delta = bounds.top - next.top;
    next.top += delta; next.bottom += delta; next.centerY += delta;
  }
  if (activeEdges.includes("bottom") && next.bottom > bounds.bottom) {
    const delta = next.bottom - bounds.bottom;
    next.top -= delta; next.bottom -= delta; next.centerY -= delta;
  }
  return next;
}

function getSerializedItemSafeZoneRect(item) {
  return normalizeSnapRect(getCopyItemBox(item));
}

function getSafeZoneViolationsForModeState(modeKey, state) {
  const safeState = state && !Array.isArray(state?.objs) && Array.isArray(state?.objects)
    ? createModeState({
        objs: sanitizeTemplateObjects(state?.objects || []),
        textLayers: Array.isArray(state?.textLayers) ? state.textLayers : [],
        bg: state?.bg || "#ffffff",
        bgType: state?.bgType || "solid",
        bg2: state?.bg2 || "#c8a06e",
        gradAngle: state?.gradAngle || 135,
        bgImageSrc: resolveStyledBgSrcForMode(state?.bgImageName || state?.bgImageSrc || null, modeKey),
        safeZone: state?.safeZone,
      })
    : createModeState(state);
  const bounds = getSafeZoneCanvasBounds(modeKey, safeState.safeZone);
  if (!bounds.activeEdges.length) return [];
  return (safeState.objs || [])
    .filter(isNonTextUserObject)
    .map((item) => {
      const rect = getSerializedItemSafeZoneRect(item);
      const edges = [];
      if (bounds.activeEdges.includes("top") && rect.top < bounds.top) edges.push("top");
      if (bounds.activeEdges.includes("bottom") && rect.bottom > bounds.bottom) edges.push("bottom");
      if (bounds.activeEdges.includes("left") && rect.left < bounds.left) edges.push("left");
      if (bounds.activeEdges.includes("right") && rect.right > bounds.right) edges.push("right");
      return edges.length ? { item, edges } : null;
    })
    .filter(Boolean);
}

function buildSafeZoneWarningData(modes = []) {
  const problematic = (Array.isArray(modes) ? modes : [])
    .map(({ modeKey, state, label }) => ({
      label,
      violations: getSafeZoneViolationsForModeState(modeKey, state),
    }))
    .map((entry) => ({
      ...entry,
      count: entry.violations.length,
      edges: [...new Set(entry.violations.flatMap((item) => item.edges))],
    }))
    .filter((entry) => entry.count > 0);
  if (!problematic.length) return null;
  const summaryParts = problematic.slice(0, 4).map((entry) => (
    `${entry.label}: ${entry.count} אלמנטים (${entry.edges.map((edge) => SAFE_ZONE_EDGE_LABELS[edge] || edge).join(", ")})`
  ));
  if (problematic.length > 4) summaryParts.push(`ועוד ${problematic.length - 4}`);
  return {
    title: "אלמנטים חוצים את קווי הבטיחות",
    body: "טקסטים נחסמים אוטומטית, אבל אלמנטים אחרים יכולים לחצות את הגבול. אפשר להמשיך או לבטל ולתקן.",
    summary: summaryParts.join(" · "),
    problematic,
  };
}

// Compute logo background color with optional opacity (for CSS background prop)
function logoBgColor(bg, opacity) {
  if (!bg || bg === 'transparent') return 'transparent';
  if ((opacity ?? 100) <= 0) return 'transparent';
  if ((opacity ?? 100) >= 100) return bg;
  try {
    const h = bg.replace('#','');
    const r = parseInt(h.slice(0,2),16), g = parseInt(h.slice(2,4),16), b = parseInt(h.slice(4,6),16);
    return `rgba(${r},${g},${b},${((opacity??100)/100).toFixed(2)})`;
  } catch(e) { return bg; }
}

function normalizeLogoOutlineColor(value) {
  const raw = String(value || "").trim();
  return /^#([0-9a-f]{6})$/i.test(raw) ? raw.toUpperCase() : DEFAULT_LOGO_OUTLINE_COLOR;
}

function hexToRgba(hex, alpha = 1) {
  const color = normalizeLogoOutlineColor(hex).replace("#", "");
  const r = parseInt(color.slice(0, 2), 16);
  const g = parseInt(color.slice(2, 4), 16);
  const b = parseInt(color.slice(4, 6), 16);
  const safeAlpha = Math.max(0, Math.min(1, Number.isFinite(alpha) ? alpha : 1));
  return `rgba(${r},${g},${b},${safeAlpha})`;
}

function makeCheckerboard() {
  const p = document.createElement("canvas");
  p.width = 16; p.height = 16;
  const ctx = p.getContext("2d");
  ctx.fillStyle = "#d0d0d0"; ctx.fillRect(0,0,16,16);
  ctx.fillStyle = "#e8e8e8"; ctx.fillRect(0,0,8,8); ctx.fillRect(8,8,8,8);
  return p;
}

function useViewportInfo(forcedMode = "auto") {
  const read = () => {
    if (typeof window === "undefined") {
      return {
        width: 1280,
        isMobile: false,
        isTablet: false,
        isPhysicalMobileDevice: false,
        isForcedMobilePreview: false,
      };
    }
    const width = window.innerWidth || 1280;
    const ua = String(navigator.userAgent || "");
    const platform = String(navigator.platform || "");
    const isTouchDevice = navigator.maxTouchPoints > 0 || 'ontouchstart' in window;
    const isPhoneUA = /iPhone|iPod|Android/i.test(ua);
    const isTabletUA = /iPad|Tablet|Android(?!.*Mobile)/i.test(ua) || (platform === "MacIntel" && navigator.maxTouchPoints > 1);
    const isDesktopPlatform = /Win32|Windows|MacIntel|Macintosh|Linux x86_64|Linux i686/i.test(platform)
      && !/Android|iPhone|iPad|iPod/i.test(ua);
    const isPhysicalMobileDevice = !!((isPhoneUA || isTabletUA) && !isDesktopPlatform);
    const autoMobile = isPhoneUA || (isTouchDevice && width <= 900);
    const autoTablet = width <= 1100;
    const isMobile = forcedMode === "mobile" ? true : forcedMode === "desktop" ? false : autoMobile;
    const isTablet = forcedMode === "desktop" ? false : forcedMode === "mobile" ? true : autoTablet;
    const isForcedMobilePreview = forcedMode === "mobile" && !isPhysicalMobileDevice;
    return {
      width,
      isMobile,
      isTablet,
      isPhysicalMobileDevice,
      isForcedMobilePreview,
      displayMode: forcedMode,
    };
  };
  const [vp, setVp] = useState(read);
  useEffect(() => {
    setVp(read());
  }, [forcedMode]);
  useEffect(() => {
    const onResize = () => setVp(read());
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [forcedMode]);
  return vp;
}

function readMobileViewportHeight() {
  if (typeof window === "undefined") return 800;
  const vv = window.visualViewport;
  const next = Math.round(vv?.height || window.innerHeight || document.documentElement?.clientHeight || 800);
  return Math.max(320, next);
}

function useMobileViewportHeight(enabled) {
  const [height, setHeight] = useState(() => readMobileViewportHeight());
  useEffect(() => {
    if (!enabled || typeof window === "undefined") return undefined;
    const update = () => setHeight(readMobileViewportHeight());
    // iOS/Android: orientationchange fires BEFORE innerHeight updates.
    // Re-read at multiple delays to catch the settled value.
    const timers = [];
    const onOrientationChange = () => {
      update();
      timers.push(setTimeout(update, 80));
      timers.push(setTimeout(update, 200));
      timers.push(setTimeout(update, 500));
    };
    update();
    const vv = window.visualViewport;
    window.addEventListener("resize", update);
    window.addEventListener("orientationchange", onOrientationChange);
    vv?.addEventListener("resize", update);
    vv?.addEventListener("scroll", update);
    return () => {
      timers.forEach(clearTimeout);
      window.removeEventListener("resize", update);
      window.removeEventListener("orientationchange", onOrientationChange);
      vv?.removeEventListener("resize", update);
      vv?.removeEventListener("scroll", update);
    };
  }, [enabled]);
  return height;
}

function useElementWidth(targetRef, fallback = 0) {
  const [width, setWidth] = useState(fallback);
  useEffect(() => {
    const node = targetRef.current;
    if (!node || typeof window === "undefined") return undefined;
    let frame = null;
    const update = () => {
      const next = Math.round(node.clientWidth || node.getBoundingClientRect().width || fallback);
      setWidth(next || fallback);
    };
    const schedule = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = requestAnimationFrame(update);
    };
    update();
    let observer = null;
    if (typeof ResizeObserver !== "undefined") {
      observer = new ResizeObserver(schedule);
      observer.observe(node);
    }
    window.addEventListener("resize", schedule);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      window.removeEventListener("resize", schedule);
      if (observer) observer.disconnect();
    };
  }, [fallback, targetRef]);
  return width;
}

function getElementInnerBoxSize(node, fallbackWidth = 0, fallbackHeight = 0) {
  if (!node || typeof window === "undefined") {
    return { width: fallbackWidth, height: fallbackHeight };
  }
  const styles = window.getComputedStyle(node);
  const padX = (parseFloat(styles.paddingLeft || "0") || 0) + (parseFloat(styles.paddingRight || "0") || 0);
  const padY = (parseFloat(styles.paddingTop || "0") || 0) + (parseFloat(styles.paddingBottom || "0") || 0);
  const width = Math.max(0, Math.round((node.clientWidth || fallbackWidth) - padX));
  const height = Math.max(0, Math.round((node.clientHeight || fallbackHeight) - padY));
  return {
    width: width || fallbackWidth,
    height: height || fallbackHeight,
  };
}

function FrameStyleIcon({ style, active }) {
  const c1 = active ? "#8B3DFF" : "#C4C9D4";
  const c2 = active ? "rgba(139,61,255,0.12)" : "#F3F4F6";
  const W = 44, H = 32;
  if (style === "classic") return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} fill="none">
      <rect x={.5} y={.5} width={W-1} height={H-1} rx={2} fill="#fff" stroke={c1} strokeWidth={1.2}/>
      <rect x={4} y={4} width={W-8} height={H-12} rx={1} fill={c2}/>
    </svg>
  );
  if (style === "thin") return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} fill="none">
      <rect x={.5} y={.5} width={W-1} height={H-1} rx={2} fill="#fff" stroke={c1} strokeWidth={1.2}/>
      <rect x={2} y={2} width={W-4} height={H-7} rx={1} fill={c2}/>
    </svg>
  );
  if (style === "strip") return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} fill="none">
      <rect x={.5} y={.5} width={W-1} height={H-1} rx={2} fill="#fff" stroke={c1} strokeWidth={1.2}/>
      <rect x={.5} y={.5} width={W-1} height={H-5.5} rx={2} fill={c2}/>
      <line x1={.5} y1={H-5} x2={W-.5} y2={H-5} stroke={c1} strokeWidth={.8}/>
    </svg>
  );
  // none
  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} fill="none">
      <rect x={.5} y={.5} width={W-1} height={H-1} rx={2} fill={c2} stroke={c1} strokeWidth={1.2} strokeDasharray="3 2"/>
    </svg>
  );
}

function ViewModeToggle({ displayMode = "auto", onChange, dark = false, compact = false }) {
  const bg = dark ? "rgba(255,255,255,.1)" : "#FFFFFF";
  const border = dark ? "1px solid rgba(255,255,255,.18)" : "1px solid #E5E7EB";
  const activeBg = dark ? "linear-gradient(135deg,#00C4CC 0%,#8B3DFF 100%)" : "linear-gradient(135deg,#00C4CC 0%,#8B3DFF 100%)";
  const activeColor = "#fff";
  const idleColor = dark ? "rgba(255,255,255,.76)" : "#6B7280";
  const iconColor = active => active ? activeColor : idleColor;
  const btnSize = compact ? 26 : 34;
  const iconFor = (id, active) => {
    const color = iconColor(active);
    if (id === "mobile") {
      return (
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <rect x="7" y="2.75" width="10" height="18.5" rx="2.2" stroke={color} strokeWidth="1.8"/>
          <path d="M10 5.5h4" stroke={color} strokeWidth="1.8" strokeLinecap="round"/>
          <circle cx="12" cy="18" r="1" fill={color}/>
        </svg>
      );
    }
    if (id === "desktop") {
      return (
        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <rect x="3" y="5" width="18" height="11" rx="2.2" stroke={color} strokeWidth="1.8"/>
          <path d="M9 19h6" stroke={color} strokeWidth="1.8" strokeLinecap="round"/>
          <path d="M10.2 16.5l-1.1 2.5M13.8 16.5l1.1 2.5" stroke={color} strokeWidth="1.6" strokeLinecap="round"/>
        </svg>
      );
    }
    return <span style={{ fontSize:13, lineHeight:1, fontWeight:800 }}>A</span>;
  };
  return (
    <div style={{ display:"inline-flex", alignItems:"center", gap:compact?1:2, padding:compact?2:3, borderRadius:999, background:bg, border, backdropFilter:dark?"blur(10px)":"none" }}>
      {[["auto","אוטומטי"],["mobile","מובייל"],["desktop","דסקטופ"]].map(([id,title]) => {
        const active = displayMode===id;
        return (
        <button
          key={id}
          onClick={() => onChange?.(id)}
          title={title}
          style={{
            border:"none",
            borderRadius:999,
            width:btnSize,
            height:btnSize,
            background:active ? activeBg : "transparent",
            color:active ? activeColor : idleColor,
            cursor:"pointer",
            fontSize:compact?11:13,
            fontWeight:700,
            fontFamily:"'Inter','Heebo',sans-serif",
            whiteSpace:"nowrap",
            display:"inline-flex",
            alignItems:"center",
            justifyContent:"center",
            transition:"all 0.2s ease",
          }}
        >
          {iconFor(id, active)}
        </button>
      )})}
    </div>
  );
}

