      objs: canvas ? serializeObjs(canvas) : [],
      textLayers: textLayersOverride,
      bg: bgRef.current,
      bgType: bgTypeRef.current,
      bg2: bgColor2Ref.current,
      gradAngle: bgGradAngleRef.current,
