      const loadFamilies = [uiFontFamily, FABRIC_FONT_FALLBACKS[uiFontFamily]].filter(Boolean);
      Promise.allSettled(loadFamilies.map((family) => document.fonts.load(`16px "${family}"`))).then(runRefresh);
