    const bounds = getSafeZoneCanvasBounds(mode, safeZone);
    const currentScale = Math.max(scale || 1, 0.001);
    const stroke = Math.max(1, 1.25 / currentScale);
    const dash = [Math.max(6, 7 / currentScale), Math.max(4, 4 / currentScale)];
