    if (safeZone.bottom.on) lines.push(new window.fabric.Line([0, bounds.bottom, dims.w, bounds.bottom], { id: "__safe_zone__bottom", stroke: "#F97316", strokeWidth: stroke, strokeDashArray: dash, selectable: false, evented: false, excludeFromExport: true, visible: lineVisible, _isSafeZoneLine: true, _isSystemOverlay: true, opacity: 0.95 }));
    if (safeZone.left.on) lines.push(new window.fabric.Line([bounds.left, 0, bounds.left, dims.h], { id: "__safe_zone__left", stroke: "#F97316", strokeWidth: stroke, strokeDashArray: dash, selectable: false, evented: false, excludeFromExport: true, visible: lineVisible, _isSafeZoneLine: true, _isSystemOverlay: true, opacity: 0.95 }));
    if (safeZone.right.on) lines.push(new window.fabric.Line([bounds.right, 0, bounds.right, dims.h], { id: "__safe_zone__right", stroke: "#F97316", strokeWidth: stroke, strokeDashArray: dash, selectable: false, evented: false, excludeFromExport: true, visible: lineVisible, _isSafeZoneLine: true, _isSystemOverlay: true, opacity: 0.95 }));
    lines.forEach((line) => canvas.add(line));
